cat > xsv_impl/src/csv_core.rs << 'RUST_EOF'
// CSV parser and writer

use std::io::{self, Read, BufRead, Write, BufWriter};
use std::fs::File;

#[derive(Debug, Clone)]
pub struct CsvConfig {
    pub delimiter: u8,
    pub quote: u8,
    pub escape: Option<u8>,
    pub no_quoting: bool,
    pub has_headers: bool,
}

impl Default for CsvConfig {
    fn default() -> Self {
        CsvConfig {
            delimiter: b',',
            quote: b'"',
            escape: None,
            no_quoting: false,
            has_headers: true,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Record {
    pub fields: Vec<Vec<u8>>,
}

impl Record {
    pub fn new() -> Self {
        Record { fields: Vec::new() }
    }

    pub fn len(&self) -> usize {
        self.fields.len()
    }

    pub fn is_empty(&self) -> bool {
        self.fields.is_empty()
    }

    pub fn get(&self, idx: usize) -> Option<&[u8]> {
        self.fields.get(idx).map(|v| v.as_slice())
    }

    pub fn get_str(&self, idx: usize) -> Option<&str> {
        self.fields.get(idx).and_then(|v| std::str::from_utf8(v).ok())
    }
}

pub struct CsvReader<R: Read> {
    reader: R,
    config: CsvConfig,
    buf: Vec<u8>,
    pos: usize,
    len: usize,
    byte_offset: u64,
    eof: bool,
}

impl<R: Read> CsvReader<R> {
    pub fn new(reader: R, config: CsvConfig) -> Self {
        CsvReader {
            reader,
            config,
            buf: vec![0u8; 65536],
            pos: 0,
            len: 0,
            byte_offset: 0,
            eof: false,
        }
    }

    pub fn byte_offset(&self) -> u64 {
        self.byte_offset
    }

    fn fill_buf(&mut self) -> io::Result<bool> {
        if self.pos >= self.len {
            self.pos = 0;
            self.len = self.reader.read(&mut self.buf)?;
            if self.len == 0 {
                self.eof = true;
                return Ok(false);
            }
        }
        Ok(true)
    }

    fn peek(&mut self) -> io::Result<Option<u8>> {
        if self.pos >= self.len {
            if !self.fill_buf()? {
                return Ok(None);
            }
        }
        if self.pos < self.len {
            Ok(Some(self.buf[self.pos]))
        } else {
            Ok(None)
        }
    }

    fn next_byte(&mut self) -> io::Result<Option<u8>> {
        if self.pos >= self.len {
            if !self.fill_buf()? {
                return Ok(None);
            }
        }
        if self.pos < self.len {
            let b = self.buf[self.pos];
            self.pos += 1;
            self.byte_offset += 1;
            Ok(Some(b))
        } else {
            Ok(None)
        }
    }

    pub fn read_record(&mut self, record: &mut Record) -> io::Result<bool> {
        record.fields.clear();

        // Check if we're at EOF
        if let Some(_) = self.peek()? {
            // continue
        } else {
            return Ok(false);
        }

        let mut field = Vec::new();
        let delim = self.config.delimiter;
        let quote = self.config.quote;

        loop {
            match self.peek()? {
                None => {
                    // EOF
                    if !field.is_empty() || !record.fields.is_empty() {
                        record.fields.push(field);
                    }
                    break;
                }
                Some(b'\n') => {
                    self.next_byte()?;
                    record.fields.push(field);
                    break;
                }
                Some(b'\r') => {
                    self.next_byte()?;
                    // Check for \r\n
                    if let Some(b'\n') = self.peek()? {
                        self.next_byte()?;
                    }
                    record.fields.push(field);
                    break;
                }
                Some(b) if b == delim => {
                    self.next_byte()?;
                    record.fields.push(field);
                    field = Vec::new();
                }
                Some(b) if b == quote && !self.config.no_quoting && field.is_empty() => {
                    self.next_byte()?; // consume opening quote
                    loop {
                        match self.next_byte()? {
                            None => break,
                            Some(b) if b == quote => {
                                // Check for escaped quote or end of field
                                if let Some(esc) = self.config.escape {
                                    // With escape char, quote just ends field
                                    break;
                                }
                                // Double-quote escape
                                match self.peek()? {
                                    Some(b2) if b2 == quote => {
                                        self.next_byte()?;
                                        field.push(quote);
                                    }
                                    _ => break,
                                }
                            }
                            Some(b) if Some(b) == self.config.escape => {
                                // Escape character
                                if let Some(next) = self.next_byte()? {
                                    field.push(next);
                                }
                            }
                            Some(b) => field.push(b),
                        }
                    }
                }
                Some(_) => {
                    let b = self.next_byte()?.unwrap();
                    field.push(b);
                }
            }
        }

        // Skip blank lines (records with a single empty field)
        if record.fields.len() == 1 && record.fields[0].is_empty() {
            return self.read_record(record);
        }

        Ok(!record.fields.is_empty())
    }
}

pub struct CsvWriter<W: Write> {
    writer: BufWriter<W>,
    delimiter: u8,
    quote: u8,
    escape: Option<u8>,
    quote_always: bool,
    crlf: bool,
    ascii: bool,
}

impl<W: Write> CsvWriter<W> {
    pub fn new(writer: W) -> Self {
        CsvWriter {
            writer: BufWriter::new(writer),
            delimiter: b',',
            quote: b'"',
            escape: None,
            quote_always: false,
            crlf: false,
            ascii: false,
        }
    }

    pub fn with_delimiter(mut self, d: u8) -> Self {
        self.delimiter = d;
        self
    }

    pub fn with_quote(mut self, q: u8) -> Self {
        self.quote = q;
        self
    }

    pub fn with_escape(mut self, e: Option<u8>) -> Self {
        self.escape = e;
        self
    }

    pub fn with_quote_always(mut self, qa: bool) -> Self {
        self.quote_always = qa;
        self
    }

    pub fn with_crlf(mut self, crlf: bool) -> Self {
        self.crlf = crlf;
        self
    }

    pub fn with_ascii(mut self, ascii: bool) -> Self {
        self.ascii = ascii;
        self
    }

    pub fn write_record(&mut self, record: &[&[u8]]) -> io::Result<()> {
        for (i, field) in record.iter().enumerate() {
            if i > 0 {
                if self.ascii {
                    self.writer.write_all(&[0x1f])?;
                } else {
                    self.writer.write_all(&[self.delimiter])?;
                }
            }
            self.write_field(field)?;
        }
        if self.ascii {
            self.writer.write_all(&[0x1e])?;
        } else if self.crlf {
            self.writer.write_all(b"\r\n")?;
        } else {
            self.writer.write_all(b"\n")?;
        }
        Ok(())
    }

    pub fn write_record_from_strs(&mut self, record: &[&str]) -> io::Result<()> {
        let bytes: Vec<&[u8]> = record.iter().map(|s| s.as_bytes()).collect();
        self.write_record(&bytes)
    }

    fn write_field(&mut self, field: &[u8]) -> io::Result<()> {
        let delim = self.delimiter;
        let quote = self.quote;

