        if self.pos < self.len {
            let b = self.buf[self.pos];
            self.pos += 1;
            self.byte_offset += 1;
            Ok(Some(b))
        } else {
            Ok(None)
        }
    }

    pub fn read_record(&mut self, record: &mut Record) -> io::Result<bool> {
        record.fields.clear();

        // Check if we're at EOF
        if let Some(_) = self.peek()? {
            // continue
        } else {
            return Ok(false);
        }

        let mut field = Vec::new();
        let delim = self.config.delimiter;
        let quote = self.config.quote;

        loop {
            match self.peek()? {
                None => {
                    // EOF
                    if !field.is_empty() || !record.fields.is_empty() {
                        record.fields.push(field);
                    }
                    break;
                }
                Some(b'\n') => {
                    self.next_byte()?;
                    record.fields.push(field);
                    break;
                }
                Some(b'\r') => {
                    self.next_byte()?;
                    // Check for \r\n
                    if let Some(b'\n') = self.peek()? {
                        self.next_byte()?;
                    }
                    record.fields.push(field);
                    break;
                }
                Some(b) if b == delim => {
                    self.next_byte()?;
                    record.fields.push(field);
                    field = Vec::new();
                }
                Some(b) if b == quote && !self.config.no_quoting && field.is_empty() => {
                    self.next_byte()?; // consume opening quote
                    loop {
                        match self.next_byte()? {
                            None => break,
                            Some(b) if b == quote => {
                                // Check for escaped quote or end of field
                                if let Some(esc) = self.config.escape {
                                    // With escape char, quote just ends field
                                    break;
                                }
                                // Double-quote escape
                                match self.peek()? {
                                    Some(b2) if b2 == quote => {
                                        self.next_byte()?;
                                        field.push(quote);
                                    }
                                    _ => break,
                                }
                            }
                            Some(b) if Some(b) == self.config.escape => {
                                // Escape character
                                if let Some(next) = self.next_byte()? {
                                    field.push(next);
                                }
                            }
                            Some(b) => field.push(b),
                        }
                    }
                }
                Some(_) => {
                    let b = self.next_byte()?.unwrap();
                    field.push(b);
                }
            }
        }

        // Skip blank lines (records with a single empty field)
        if record.fields.len() == 1 && record.fields[0].is_empty() {
            return self.read_record(record);
        }

        Ok(!record.fields.is_empty())
    }
}

pub struct CsvWriter<W: Write> {
    writer: BufWriter<W>,
    delimiter: u8,
    quote: u8,
    escape: Option<u8>,
    quote_always: bool,
    crlf: bool,
    ascii: bool,
}

impl<W: Write> CsvWriter<W> {
    pub fn new(writer: W) -> Self {
        CsvWriter {
            writer: BufWriter::new(writer),
            delimiter: b',',
            quote: b'"',
            escape: None,
            quote_always: false,
            crlf: false,
            ascii: false,
        }
    }

    pub fn with_delimiter(mut self, d: u8) -> Self {
        self.delimiter = d;
        self
    }

    pub fn with_quote(mut self, q: u8) -> Self {
        self.quote = q;
        self
    }

    pub fn with_escape(mut self, e: Option<u8>) -> Self {
        self.escape = e;
        self
    }

    pub fn with_quote_always(mut self, qa: bool) -> Self {
        self.quote_always = qa;
        self
    }

    pub fn with_crlf(mut self, crlf: bool) -> Self {
        self.crlf = crlf;
        self
    }

    pub fn with_ascii(mut self, ascii: bool) -> Self {
        self.ascii = ascii;
        self
    }

    pub fn write_record(&mut self, record: &[&[u8]]) -> io::Result<()> {
        for (i, field) in record.iter().enumerate() {
            if i > 0 {
                if self.ascii {
                    self.writer.write_all(&[0x1f])?;
                } else {
                    self.writer.write_all(&[self.delimiter])?;
                }
            }
            self.write_field(field)?;
        }
        if self.ascii {
            self.writer.write_all(&[0x1e])?;
        } else if self.crlf {
            self.writer.write_all(b"\r\n")?;
        } else {
            self.writer.write_all(b"\n")?;
        }
        Ok(())
    }

    pub fn write_record_from_strs(&mut self, record: &[&str]) -> io::Result<()> {
        let bytes: Vec<&[u8]> = record.iter().map(|s| s.as_bytes()).collect();
        self.write_record(&bytes)
    }

    fn write_field(&mut self, field: &[u8]) -> io::Result<()> {
        let delim = self.delimiter;
        let quote = self.quote;

        let needs_quoting = if self.ascii {
            false
        } else if self.quote_always {
            true
        } else {
            field.contains(&delim) || field.contains(&quote) || 
            field.contains(&b'\n') || field.contains(&b'\r')
        };

        if needs_quoting {
            self.writer.write_all(&[quote])?;
            for &b in field {
                if b == quote {
                    if let Some(esc) = self.escape {
                        self.writer.write_all(&[esc, quote])?;
                    } else {
                        self.writer.write_all(&[quote, quote])?;
                    }
                } else {
                    self.writer.write_all(&[b])?;
                }
            }
            self.writer.write_all(&[quote])?;
        } else {
            self.writer.write_all(field)?;
        }
        Ok(())
    }

    pub fn flush(&mut self) -> io::Result<()> {
        self.writer.flush()
    }
}

// Helper to open a file or use stdin
pub fn open_input(path: Option<&str>) -> io::Result<Box<dyn Read>> {
    match path {
        None | Some("-") => Ok(Box::new(io::stdin())),
        Some(p) => {
            let f = File::open(p).map_err(|e| {
                io::Error::new(e.kind(), format!("failed to open {}: {}", p, e))
            })?;
            Ok(Box::new(f))
        }
    }
}

pub fn open_output(path: Option<&str>) -> io::Result<Box<dyn Write>> {
    match path {
        None | Some("-") => Ok(Box::new(io::stdout())),
        Some(p) => {
            let f = File::create(p).map_err(|e| {
                io::Error::new(e.kind(), format!("failed to create {}: {}", p, e))
            })?;
            Ok(Box::new(f))
        }
    }
}

pub fn parse_delimiter(s: &str) -> Result<u8, String> {
    let bytes = s.as_bytes();
    if bytes.len() == 1 {
        Ok(bytes[0])
    } else {
        Err(format!("Delimiter must be a single character, got: {}", s))
    }
}
