// Column selection parser and applicator

#[derive(Debug, Clone)]
pub enum Selector {
    Index(usize),   // 1-based
    Name(String),
    IndexRange(Option<usize>, Option<usize>),  // 1-based, inclusive
    NameRange(String, String),
    Negate(Vec<Selector>),
}

#[derive(Debug, Clone)]
pub struct Selection {
    pub selectors: Vec<Selector>,
}

impl Selection {
    pub fn parse(spec: &str) -> Result<Self, String> {
        if spec.is_empty() {
            return Err("Empty selection".to_string());
        }

        // Check if it starts with '!'  (negation)
        if spec.starts_with('!') {
            let inner = Selection::parse(&spec[1..])?;
            return Ok(Selection {
                selectors: vec![Selector::Negate(inner.selectors)],
            });
        }

        let mut selectors = Vec::new();
        let mut rest = spec;

        while !rest.is_empty() {
            let (sel, remaining) = parse_one_selector(rest)?;
            selectors.push(sel);
            rest = remaining;
            if rest.starts_with(',') {
                rest = &rest[1..];
            }
        }

        Ok(Selection { selectors })
    }

    pub fn indices(&self, headers: &[Vec<u8>]) -> Result<Vec<usize>, String> {
        let mut result = Vec::new();
        self.collect_indices(&self.selectors, headers, &mut result)?;
        Ok(result)
    }

    fn collect_indices(&self, selectors: &[Selector], headers: &[Vec<u8>], result: &mut Vec<usize>) -> Result<(), String> {
        for sel in selectors {
            match sel {
                Selector::Index(i) => {
                    if *i == 0 || *i > headers.len() {
                        return Err(format!("Column index {} out of range (1-{})", i, headers.len()));
                    }
                    result.push(*i - 1);
                }
                Selector::Name(name) => {
                    let mut found = false;
                    // Support "Name[n]" syntax for nth occurrence
                    let (base_name, occurrence) = parse_name_with_occurrence(name);
                    let mut count = 0;
                    for (i, h) in headers.iter().enumerate() {
                        if h == base_name.as_bytes() {
                            count += 1;
                            if count == occurrence {
                                result.push(i);
                                found = true;
                                break;
                            }
                        }
                    }
                    if !found {
                        return Err(format!("No column named '{}'", name));
                    }
                }
                Selector::IndexRange(start, end) => {
                    let s = start.unwrap_or(1);
                    let e = end.unwrap_or(headers.len());
                    if s == 0 {
                        return Err("Column index must be >= 1".to_string());
                    }
                    if e > headers.len() {
                        return Err(format!("Column index {} out of range (1-{})", e, headers.len()));
                    }
                    if s > e {
                        for i in (e..=s).rev() {
                            result.push(i - 1);
                        }
                    } else {
                        for i in s..=e {
                            result.push(i - 1);
                        }
                    }
                }
                Selector::NameRange(start, end) => {
                    let start_idx = find_header_index(headers, start)?;
                    let end_idx = find_header_index(headers, end)?;
                    if start_idx <= end_idx {
                        for i in start_idx..=end_idx {
                            result.push(i);
                        }
                    } else {
                        for i in (end_idx..=start_idx).rev() {
                            result.push(i);
                        }
                    }
                }
                Selector::Negate(inner) => {
                    let mut excluded = Vec::new();
                    self.collect_indices(inner, headers, &mut excluded)?;
                    for i in 0..headers.len() {
                        if !excluded.contains(&i) {
                            result.push(i);
                        }
                    }
                }
            }
        }
        Ok(())
    }
}

fn parse_name_with_occurrence(name: &str) -> (String, usize) {
    if let Some(bracket_pos) = name.rfind('[') {
        if name.ends_with(']') {
            let num_str = &name[bracket_pos+1..name.len()-1];
            if let Ok(n) = num_str.parse::<usize>() {
                return (name[..bracket_pos].to_string(), n);
            }
        }
    }
    (name.to_string(), 1)
}

fn find_header_index(headers: &[Vec<u8>], name: &str) -> Result<usize, String> {
    let (base_name, occurrence) = parse_name_with_occurrence(name);
    let mut count = 0;
    for (i, h) in headers.iter().enumerate() {
        if h == base_name.as_bytes() {
            count += 1;
            if count == occurrence {
                return Ok(i);
            }
        }
    }
    Err(format!("No column named '{}'", name))
}

fn parse_one_selector(s: &str) -> Result<(Selector, &str), String> {
    // Quoted name: "..."
    if s.starts_with('"') {
        return parse_quoted_name(s);
    }

    // Find the end of this selector (next unescaped comma)
    // But handle ranges with '-'
    let part_end = find_selector_end(s);
    let part = &s[..part_end];
    let rest = &s[part_end..];

    let sel = parse_selector_part(part)?;
    Ok((sel, rest))
}

fn find_selector_end(s: &str) -> usize {
    // Find next comma that's not inside brackets
    let mut depth = 0;
    for (i, c) in s.char_indices() {
        match c {
            '[' => depth += 1,
            ']' => depth -= 1,
            ',' if depth == 0 => return i,
            _ => {}
        }
    }
    s.len()
}

fn parse_quoted_name(s: &str) -> Result<(Selector, &str), String> {
    // s starts with '"'
    let mut i = 1;
    let bytes = s.as_bytes();
    let mut name = Vec::new();
    while i < bytes.len() {
        if bytes[i] == b'"' {
            i += 1;
            if i < bytes.len() && bytes[i] == b'"' {
                name.push(b'"');
                i += 1;
            } else {
                break;
            }
        } else {
            name.push(bytes[i]);
            i += 1;
        }
    }
    let name_str = String::from_utf8(name).map_err(|e| e.to_string())?;
    let rest = &s[i..];

    // Check if it's a range
    if rest.starts_with('-') {
        let rest2 = &rest[1..];
        let end_pos = find_selector_end(rest2);
        let end_part = &rest2[..end_pos];
        let remaining = &rest2[end_pos..];
        // end_part could also be a quoted name
        let end_name = if end_part.starts_with('"') {
            let (end_sel, _) = parse_quoted_name(end_part)?;
            if let Selector::Name(n) = end_sel { n } else { end_part.to_string() }
        } else {
            end_part.to_string()
        };
        return Ok((Selector::NameRange(name_str, end_name), remaining));
    }

    Ok((Selector::Name(name_str), rest))
}

fn parse_selector_part(part: &str) -> Result<Selector, String> {
    if part.is_empty() {
        return Err("Empty selector part".to_string());
    }

    // Check for range with '-'
    if let Some(dash_pos) = find_range_dash(part) {
        let left = &part[..dash_pos];
        let right = &part[dash_pos+1..];

        let left_is_num = !left.is_empty() && left.bytes().all(|b| b.is_ascii_digit());
        let right_is_num = !right.is_empty() && right.bytes().all(|b| b.is_ascii_digit());
        let left_empty = left.is_empty();
        let right_empty = right.is_empty();

        if (left_is_num || left_empty) && (right_is_num || right_empty) {
            let start = if left_empty { None } else { Some(left.parse::<usize>().unwrap()) };
            let end = if right_empty { None } else { Some(right.parse::<usize>().unwrap()) };
            return Ok(Selector::IndexRange(start, end));
        } else {
            // Name range
            return Ok(Selector::NameRange(left.to_string(), right.to_string()));
        }
    }

    // Try as index
    if !part.is_empty() && part.bytes().all(|b| b.is_ascii_digit()) {
        let idx = part.parse::<usize>().map_err(|e| e.to_string())?;
        return Ok(Selector::Index(idx));
    }

    // Name (possibly with [n])
    Ok(Selector::Name(part.to_string()))
}

fn find_range_dash(s: &str) -> Option<usize> {
    // Find a '-' that separates a range, but not inside brackets
    // Don't match leading '-' for negative (there are none in column specs)
    let bytes = s.as_bytes();
    let mut depth = 0;
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'[' => depth += 1,
            b']' => depth -= 1,
            b'-' if depth == 0 && i > 0 => return Some(i),
            _ => {}
        }
        i += 1;
    }
    // Check for trailing dash (like "3-")
    if bytes.last() == Some(&b'-') {
        return Some(bytes.len() - 1);
    }
    None
}

// Apply selection to a record given headers (0-based indices)
pub fn apply_selection(record: &[Vec<u8>], indices: &[usize]) -> Vec<Vec<u8>> {
    indices.iter().map(|&i| {
        if i < record.len() {
            record[i].clone()
        } else {
            Vec::new()
        }
    }).collect()
}

pub fn apply_selection_refs<'a>(record: &'a [Vec<u8>], indices: &[usize]) -> Vec<&'a [u8]> {
    indices.iter().map(|&i| {
        if i < record.len() {
            record[i].as_slice()
        } else {
            &[] as &[u8]
        }
    }).collect()
}
