// Common configuration and argument parsing helpers

use std::io;
use crate::csv_core::{CsvConfig, CsvReader, CsvWriter, open_input, open_output};

pub struct Config {
    pub path: Option<String>,
    pub delimiter: u8,
    pub has_headers: bool,
    pub output: Option<String>,
}

impl Config {
    pub fn new() -> Self {
        Config {
            path: None,
            delimiter: b',',
            has_headers: true,
            output: None,
        }
    }

    pub fn csv_config(&self) -> CsvConfig {
        CsvConfig {
            delimiter: self.delimiter,
            quote: b'"',
            escape: None,
            no_quoting: false,
            has_headers: self.has_headers,
        }
    }
}

pub fn get_flag(args: &[String], flag: &str) -> bool {
    args.iter().any(|a| a == flag)
}

pub fn get_opt<'a>(args: &'a [String], flag: &str) -> Option<&'a str> {
    for i in 0..args.len() {
        if args[i] == flag && i + 1 < args.len() {
            return Some(&args[i + 1]);
        }
        if args[i].starts_with(flag) && args[i].as_bytes().get(flag.len()) == Some(&b'=') {
            return Some(&args[i][flag.len() + 1..]);
        }
    }
    None
}

pub fn get_positional(args: &[String]) -> Vec<&str> {
    let mut result = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "--" {
            i += 1;
            while i < args.len() {
                result.push(args[i].as_str());
                i += 1;
            }
            break;
        } else if a.starts_with('-') && a.len() > 1 {
            // Skip flags and their values
            let known_opts = ["-o", "--output", "-d", "--delimiter", "-s", "--select",
                              "-l", "--length", "-e", "--end", "--start", "--len", "--index",
                              "-i", "--index", "-c", "--condense", "--separator", "-t",
                              "--out-delimiter", "--quote", "--escape", "-j", "--jobs",
                              "-a", "--asc", "--seed", "-p", "--pad", "--filename",
                              "--prefix-length", "-N", "-R", "--size", "-w", "--width"];
            let is_valued_opt = known_opts.iter().any(|&o| a == o);
            if is_valued_opt {
                i += 2;
            } else {
                i += 1;
            }
        } else {
            result.push(a.as_str());
            i += 1;
        }
    }
    result
}
