// Index file format for xsv

use std::io::{self, Read, Write, Seek, SeekFrom};
use std::fs::{File, OpenOptions};

/// Index stores:
/// - N+1 byte offsets (for header + N data rows), as u64 big-endian
/// - 1 row count (total rows including header), as u64 big-endian
/// Total: (N+2) * 8 bytes

pub struct CsvIndex {
    pub offsets: Vec<u64>,  // byte offsets for each row (including header if present)
    pub num_records: u64,   // number of data records (not counting header)
}

impl CsvIndex {
    pub fn from_file(path: &str) -> io::Result<Self> {
        let idx_path = format!("{}.idx", path);
        let mut f = File::open(&idx_path)?;
        let mut data = Vec::new();
        f.read_to_end(&mut data)?;

        if data.len() < 8 || data.len() % 8 != 0 {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "Invalid index file"));
        }

        let n_values = data.len() / 8;
        let mut values = Vec::with_capacity(n_values);
        for i in 0..n_values {
            let mut bytes = [0u8; 8];
            bytes.copy_from_slice(&data[i*8..(i+1)*8]);
            values.push(u64::from_be_bytes(bytes));
        }

        // Last value is num_records (total rows including header)
        let total_rows = *values.last().unwrap();
        let offsets = values[..values.len()-1].to_vec();
        let num_records = if total_rows > offsets.len() as u64 { 
            // shouldn't happen
            total_rows
        } else {
            total_rows
        };

        Ok(CsvIndex {
            offsets,
            num_records: total_rows,
        })
    }

    pub fn num_data_records(&self) -> u64 {
        // offsets has one per row (header + data rows)
        // num_records = total rows including header
        if self.num_records > 0 && !self.offsets.is_empty() {
            self.num_records - 1  // subtract header
        } else {
            0
        }
    }

    pub fn write(path: &str, offsets: &[u64], total_rows: u64) -> io::Result<()> {
        let idx_path = format!("{}.idx", path);
        let mut f = File::create(&idx_path)?;
        for &offset in offsets {
            f.write_all(&offset.to_be_bytes())?;
        }
        f.write_all(&total_rows.to_be_bytes())?;
        f.flush()?;
        Ok(())
    }

    /// Check if index is still valid for the given CSV file
    pub fn is_valid_for(path: &str) -> bool {
        let idx_path = format!("{}.idx", path);
        let csv_meta = std::fs::metadata(path).ok();
        let idx_meta = std::fs::metadata(&idx_path).ok();

        match (csv_meta, idx_meta) {
            (Some(csv_m), Some(idx_m)) => {
                // Check if index is newer than CSV
                if let (Ok(csv_time), Ok(idx_time)) = (csv_m.modified(), idx_m.modified()) {
                    idx_time >= csv_time
                } else {
                    false
                }
            }
            _ => false
        }
    }
}
