use std::process;
use crate::csv_core::{CsvConfig, CsvReader, open_input, parse_delimiter};
use crate::config::{get_flag, get_opt};

const USAGE: &str = "
Prints a count of the number of records in the CSV data.

Note that the count will not include the header row (unless --no-headers is
given).

Usage:
    xsv count [options] [<input>]

Common options:
    -h, --help             Display this message
    -n, --no-headers       When set, the first row will not be included in
                           the count.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    if get_flag(args, "--help") || get_flag(args, "-h") {
        print!("{}", USAGE);
        return;
    }

    let no_headers = get_flag(args, "--no-headers") || get_flag(args, "-n");
    let delimiter = get_opt(args, "--delimiter")
        .or_else(|| get_opt(args, "-d"))
        .map(|s| parse_delimiter(s).unwrap_or_else(|e| { eprintln!("{}", e); process::exit(1); }))
        .unwrap_or(b',');

    // Get input file
    let positional: Vec<&str> = args.iter()
        .filter(|a| !a.starts_with('-'))
        .map(|a| a.as_str())
        .collect();

    // Better positional parsing
    let input_path = get_positional_args(args);

    let input = open_input(input_path.first().map(|s| s.as_str())).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: !no_headers,
    };

    let mut reader = CsvReader::new(input, config);
    let mut record = crate::csv_core::Record::new();

    let mut count = 0u64;

    // Skip header if has headers
    if !no_headers {
        if !reader.read_record(&mut record).unwrap_or(false) {
            println!("0");
            return;
        }
    }

    while reader.read_record(&mut record).unwrap_or(false) {
        count += 1;
    }

    println!("{}", count);
}

fn get_positional_args(args: &[String]) -> Vec<String> {
    let mut result = Vec::new();
    let mut i = 0;
    let opts_with_val = ["--delimiter", "-d", "--output", "-o"];
    while i < args.len() {
        if args[i] == "--" {
            i += 1;
            while i < args.len() {
                result.push(args[i].clone());
                i += 1;
            }
            break;
        } else if args[i].starts_with('-') && args[i].len() > 1 && args[i] != "-" {
            if opts_with_val.contains(&args[i].as_str()) {
                i += 2;
            } else {
                i += 1;
            }
        } else {
            result.push(args[i].clone());
