use std::process;
use crate::csv_core::{CsvConfig, CsvReader, open_input, parse_delimiter};
use crate::util::{Args, make_reader};

const USAGE: &str = "
Prints the fields of the first row in the CSV data.

These names can be used in commands like 'select' to refer to columns in the
CSV data.

Note that multiple CSV files may be given to this command. This is useful with
the --intersect flag.

Usage:
    xsv headers [options] [<input>...]

headers options:
    -j, --just-names       Only show the header names (hide column index).
                           This is automatically enabled if more than one
                           input is given.
    --intersect            Shows the intersection of all headers in all of
                           the inputs given.

Common options:
    -h, --help             Display this message
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let just_names = a.flag2("--just-names", "-j");
    let intersect = a.flag("--intersect");
    let delimiter = a.delimiter();

    let pos = a.positional();

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    // Multiple inputs
    let show_just_names = just_names || pos.len() > 1;

    if pos.is_empty() {
        // Read from stdin
        let input = open_input(None).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
        let mut reader = CsvReader::new(input, config.clone());
        let mut record = crate::csv_core::Record::new();
        if reader.read_record(&mut record).unwrap_or(false) {
            for (i, field) in record.fields.iter().enumerate() {
                let name = std::str::from_utf8(field).unwrap_or("");
                if show_just_names {
                    println!("{}", name);
                } else {
                    println!("{:>3}   {}", i + 1, name);
                }
            }
        }
        return;
    }

    if intersect && pos.len() > 1 {
        // Find intersection
        let mut headers_sets: Vec<Vec<String>> = Vec::new();
        for path in &pos {
            let input = open_input(Some(path)).unwrap_or_else(|e| {
                eprintln!("{}", e);
                process::exit(1);
            });
            let mut reader = CsvReader::new(input, config.clone());
            let mut record = crate::csv_core::Record::new();
            if reader.read_record(&mut record).unwrap_or(false) {
                let names: Vec<String> = record.fields.iter()
                    .map(|f| String::from_utf8_lossy(f).into_owned())
                    .collect();
                headers_sets.push(names);
            }
        }

        if !headers_sets.is_empty() {
            let mut intersection: Vec<String> = headers_sets[0].clone();
            for set in &headers_sets[1..] {
                intersection.retain(|h| set.contains(h));
            }
            for name in &intersection {
                println!("{}", name);
            }
        }
        return;
    }

    for path in &pos {
        let input = open_input(Some(path)).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
        let mut reader = CsvReader::new(input, config.clone());
        let mut record = crate::csv_core::Record::new();
        if reader.read_record(&mut record).unwrap_or(false) {
            for (i, field) in record.fields.iter().enumerate() {
                let name = std::str::from_utf8(field).unwrap_or("");
                if show_just_names {
                    println!("{}", name);
                } else {
                    println!("{:>3}   {}", i + 1, name);
                }
            }
        }
    }
}
