use std::process;
use std::io::Write;
use crate::csv_core::{CsvConfig, CsvReader, open_input, open_output};
use crate::util::Args;

const USAGE: &str = "
Outputs CSV data as a table with columns in alignment.

This will not work well if the CSV data contains large fields.

Note that formatting a table requires buffering all CSV data into memory.
Therefore, you should use the 'sample' or 'slice' command to trim down large
CSV data before formatting it with this command.

Usage:
    xsv table [options] [<input>]

table options:
    -w, --width <arg>      The minimum width of each column.
                           [default: 2]
    -p, --pad <arg>        The minimum number of spaces between each column.
                           [default: 2]
    -c, --condense <arg>  Limits the length of each field to the value
                           specified. If the field is UTF-8 encoded, then
                           <arg> refers to the number of code points.
                           Otherwise, it refers to the number of bytes.

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let delimiter = a.delimiter();
    let output_path = a.output_path();
    let min_width: usize = a.opt2("--width", "-w")
        .and_then(|s| s.parse().ok())
        .unwrap_or(2);
    let pad: usize = a.opt2("--pad", "-p")
        .and_then(|s| s.parse().ok())
        .unwrap_or(2);
    let condense: Option<usize> = a.opt2("--condense", "-c")
        .and_then(|s| s.parse().ok());

    let pos = a.positional();
    let input_path = pos.first().map(|s| s.as_str());

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut record = crate::csv_core::Record::new();

    // Buffer all records
    let mut records: Vec<Vec<String>> = Vec::new();

    while reader.read_record(&mut record).unwrap_or(false) {
        let row: Vec<String> = record.fields.iter()
            .map(|f| String::from_utf8_lossy(f).into_owned())
            .collect();
        records.push(row);
    }

    if records.is_empty() {
        return;
    }

    // Condense fields
    let records: Vec<Vec<String>> = if let Some(max_len) = condense {
        records.into_iter().map(|row| {
            row.into_iter().map(|field| condense_field(&field, max_len)).collect()
        }).collect()
    } else {
        records
    };

    // Compute column widths
    let num_cols = records.iter().map(|r| r.len()).max().unwrap_or(0);
    let mut col_widths: Vec<usize> = vec![min_width; num_cols];

    for row in &records {
        for (i, field) in row.iter().enumerate() {
            let width = display_width(field);
            if width > col_widths[i] {
                col_widths[i] = width;
            }
        }
    }

    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut out = std::io::BufWriter::new(output);

    for row in &records {
        let last = row.len().saturating_sub(1);
        for (i, field) in row.iter().enumerate() {
            if i == last {
                write!(out, "{}", field).ok();
            } else {
                let width = display_width(field);
                let needed = col_widths[i] + pad;
                write!(out, "{}", field).ok();
                for _ in 0..(needed - width) {
                    write!(out, " ").ok();
                }
            }
        }
        writeln!(out).ok();
    }

    out.flush().ok();
}

fn display_width(s: &str) -> usize {
    // For ASCII, this is just len. For UTF-8, count code points
    s.chars().count()
}

fn condense_field(s: &str, max_len: usize) -> String {
    let char_count = s.chars().count();
    if char_count <= max_len {
        s.to_string()
    } else {
        s.chars().take(max_len).collect()
    }
}
