use std::process;
use std::io::Write;
use crate::csv_core::{CsvConfig, CsvReader, open_input};
use crate::util::Args;

const USAGE: &str = "
Prints flattened records such that fields are labeled separated by a new line.
This mode is particularly useful for viewing one record at a time. Each
record is separated by a special '#' character (on a line by itself), which
can be changed with the --separator flag.

There is also a condensed view (-c or --condense) that will shorten the
contents of each field to provide a summary view.

Usage:
    xsv flatten [options] [<input>]

flatten options:
    -c, --condense <arg>  Limits the length of each field to the value
                           specified. If the field is UTF-8 encoded, then
                           <arg> refers to the number of code points.
                           Otherwise, it refers to the number of bytes.
    -s, --separator <arg>  A string of characters to write after each record.
                           When non-empty, a new line is automatically
                           appended to the separator.
                           [default: #]

Common options:
    -h, --help             Display this message
    -n, --no-headers       When set, the first row will not be interpreted
                           as headers. When set, the name of each field
                           will be its index.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let no_headers = !a.has_headers();
    let delimiter = a.delimiter();
    let condense: Option<usize> = a.opt2("--condense", "-c")
        .and_then(|s| s.parse().ok());
    let separator: String = a.opt2("--separator", "-s")
        .unwrap_or("#")
        .to_string();

    let pos = a.positional();
    let input_path = pos.first().map(|s| s.as_str());

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut record = crate::csv_core::Record::new();
    let mut out = std::io::BufWriter::new(std::io::stdout());

    let headers: Vec<String>;

    if no_headers {
        // First record to determine number of columns
        if !reader.read_record(&mut record).unwrap_or(false) {
            return;
        }
        headers = (1..=record.len()).map(|i| i.to_string()).collect();

        // Print first record
        print_flat_record(&mut out, &headers, &record, &separator, condense);

        while reader.read_record(&mut record).unwrap_or(false) {
            print_flat_record(&mut out, &headers, &record, &separator, condense);
        }
    } else {
        // Read header
        if !reader.read_record(&mut record).unwrap_or(false) {
            return;
        }
        headers = record.fields.iter()
            .map(|f| String::from_utf8_lossy(f).into_owned())
            .collect();

        while reader.read_record(&mut record).unwrap_or(false) {
            print_flat_record(&mut out, &headers, &record, &separator, condense);
        }
    }

    out.flush().ok();
}

fn print_flat_record(out: &mut impl Write, headers: &[String], record: &crate::csv_core::Record, separator: &str, condense: Option<usize>) {
    // Find max header width for alignment
    let max_width = headers.iter().map(|h| h.chars().count()).max().unwrap_or(0);

    for (i, field) in record.fields.iter().enumerate() {
        let header = headers.get(i).map(|s| s.as_str()).unwrap_or("");
        let value = std::str::from_utf8(field).unwrap_or("");
        let value = if let Some(max_len) = condense {
            let chars: String = value.chars().take(max_len).collect();
            chars
        } else {
            value.to_string()
        };

        let pad = max_width - header.chars().count();
        write!(out, "{}", header).ok();
        for _ in 0..pad {
            write!(out, " ").ok();
        }
        writeln!(out, "  {}", value).ok();
    }

    if !separator.is_empty() {
        writeln!(out, "{}", separator).ok();
    }
}
