    let out_delimiter: u8 = a.opt2("--out-delimiter", "-t")
        .map(|s| {
            if s.as_bytes().len() == 1 {
                s.as_bytes()[0]
            } else {
                eprintln!("Output delimiter must be a single character");
                process::exit(1);
            }
        })
        .unwrap_or(b',');
    let crlf = a.flag("--crlf");
    let ascii = a.flag("--ascii");
    let quote_always = a.flag("--quote-always");

    let quote: u8 = a.opt("--quote")
        .map(|s| {
            if s.as_bytes().len() == 1 {
                s.as_bytes()[0]
            } else {
                eprintln!("Quote character must be a single character");
                process::exit(1);
            }
        })
        .unwrap_or(b'"');

    let escape: Option<u8> = a.opt("--escape").map(|s| {
        if s.as_bytes().len() == 1 {
            s.as_bytes()[0]
        } else {
            eprintln!("Escape character must be a single character");
            process::exit(1);
        }
    });

    let output_path = a.output_path();
    let pos = a.positional();
    let input_path = pos.first().map(|s| s.as_str());

    let config = CsvConfig {
        delimiter: in_delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut writer = CsvWriter::new(output)
        .with_delimiter(out_delimiter)
        .with_quote(quote)
        .with_escape(escape)
        .with_quote_always(quote_always)
        .with_crlf(crlf)
        .with_ascii(ascii);

    let mut record = crate::csv_core::Record::new();

    while reader.read_record(&mut record).unwrap_or(false) {
        let refs: Vec<&[u8]> = record.fields.iter().map(|f| f.as_slice()).collect();
        writer.write_record(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    writer.flush().ok();
}
