use std::process;
use crate::csv_core::{CsvConfig, CsvReader, CsvWriter, open_input, open_output};
use crate::util::Args;
use crate::select::Selection;

const USAGE: &str = "
Filters CSV data by whether the given regex matches a row.

The regex is applied to each field in each row, and if any field matches,
then the row is written to the output. The columns to search can be limited
with the '--select' flag (but the full row is still written to the output if
there is a match).

Usage:
    xsv search [options] <regex> [<input>]
    xsv search --help

search options:
    -i, --ignore-case      Case insensitive search. This is equivalent to
                           prefixing the regex with '(?i)'.
    -s, --select <arg>     Select the columns to search. See 'xsv select -h'
                           for the full syntax.
    -v, --invert-match     Select only rows that did not match

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will not be interpreted
                           as headers. (i.e., They are not searched, analyzed,
                           sliced, etc.)
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let ignore_case = a.flag2("--ignore-case", "-i");
    let invert = a.flag2("--invert-match", "-v");
    let select = a.opt2("--select", "-s");
    let no_headers = !a.has_headers();
    let delimiter = a.delimiter();
    let output_path = a.output_path();

    let pos = a.positional();

    if pos.is_empty() {
        eprintln!("Usage: xsv search [options] <regex> [<input>]");
        process::exit(1);
    }

    let regex_str = &pos[0];
    let input_path = pos.get(1).map(|s| s.as_str());

    // Build regex
    let pattern = if ignore_case {
        format!("(?i){}", regex_str)
    } else {
