                    }
                }
                return false;
            }
            '?' => {
                if check_exact_match(pat, atom_end + 1, text, ti, target) {
                    return true;
                }
                if ti < target && matcher(text[ti]) {
                    return check_exact_match(pat, atom_end + 1, text, ti + 1, target);
                }
                return false;
            }
            _ => {}
        }
    }

    if ti >= target {
        return false;
    }
    if matcher(text[ti]) {
        return check_exact_match(pat, atom_end, text, ti + 1, target);
    }
    false
}

fn parse_atom(pat: &[char], pi: usize) -> (usize, Box<dyn Fn(char) -> bool>) {
    if pi >= pat.len() {
        return (pi, Box::new(|_| false));
    }

    match pat[pi] {
        '.' => (pi + 1, Box::new(|c: char| c != '\n')),
        '\\' if pi + 1 < pat.len() => {
            let next = pat[pi + 1];
            let matcher: Box<dyn Fn(char) -> bool> = match next {
                'd' => Box::new(|c: char| c.is_ascii_digit()),
                'D' => Box::new(|c: char| !c.is_ascii_digit()),
                'w' => Box::new(|c: char| c.is_alphanumeric() || c == '_'),
                'W' => Box::new(|c: char| !(c.is_alphanumeric() || c == '_')),
                's' => Box::new(|c: char| c.is_whitespace()),
                'S' => Box::new(|c: char| !c.is_whitespace()),
                _ => {
                    let nc = next;
                    Box::new(move |c: char| c == nc)
                }
            };
            (pi + 2, matcher)
        }
        '[' => {
            // Character class
            let (end, chars, negated) = parse_char_class(pat, pi);
            let matcher: Box<dyn Fn(char) -> bool> = if negated {
                Box::new(move |c: char| !char_in_class(c, &chars))
            } else {
                Box::new(move |c: char| char_in_class(c, &chars))
            };
            (end, matcher)
        }
        c => {
            let cc = c;
            (pi + 1, Box::new(move |ch: char| ch == cc))
        }
    }
}

#[derive(Clone)]
enum CharClassItem {
    Single(char),
    Range(char, char),
}

fn parse_char_class(pat: &[char], pi: usize) -> (usize, Vec<CharClassItem>, bool) {
    // pi points to '['
    let mut i = pi + 1;
    let negated = if i < pat.len() && pat[i] == '^' {
        i += 1;
        true
    } else {
        false
    };

    let mut items = Vec::new();
    while i < pat.len() && pat[i] != ']' {
        if i + 2 < pat.len() && pat[i + 1] == '-' && pat[i + 2] != ']' {
            items.push(CharClassItem::Range(pat[i], pat[i + 2]));
            i += 3;
        } else if pat[i] == '\\' && i + 1 < pat.len() {
            items.push(CharClassItem::Single(pat[i + 1]));
            i += 2;
        } else {
            items.push(CharClassItem::Single(pat[i]));
            i += 1;
        }
    }

    (i + 1, items, negated)
}

fn char_in_class(c: char, items: &[CharClassItem]) -> bool {
    for item in items {
        match item {
            CharClassItem::Single(ch) => if *ch == c { return true; }
            CharClassItem::Range(a, b) => if c >= *a && c <= *b { return true; }
        }
    }
    false
}

fn find_group(pat: &[char], pi: usize) -> (usize, String) {
    // pi points to '('
    let mut i = pi + 1;
    let mut depth = 1;
    let mut content = String::new();
    while i < pat.len() {
        if pat[i] == '(' {
            depth += 1;
            content.push(pat[i]);
        } else if pat[i] == ')' {
            depth -= 1;
            if depth == 0 {
                return (i + 1, content);
            }
            content.push(pat[i]);
        } else {
            content.push(pat[i]);
        }
        i += 1;
    }
    (i, content)
}

fn split_alternation(s: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut current = String::new();
    let mut depth = 0;
    for c in s.chars() {
        match c {
            '(' => { depth += 1; current.push(c); }
            ')' => { depth -= 1; current.push(c); }
            '|' if depth == 0 => {
                result.push(current.clone());
                current.clear();
            }
            _ => current.push(c),
        }
    }
    result.push(current);
    result
}

fn parse_regex(pattern: &str) -> Result<(), String> {
    // Basic validation
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    let mut depth = 0;
    while i < chars.len() {
        match chars[i] {
            '(' => depth += 1,
            ')' => {
                if depth == 0 {
                    return Err("Unmatched )".to_string());
                }
                depth -= 1;
            }
            '[' => {
                i += 1;
                if i < chars.len() && chars[i] == '^' { i += 1; }
                while i < chars.len() && chars[i] != ']' {
                    i += 1;
                }
                if i >= chars.len() {
                    return Err("Unclosed [".to_string());
                }
            }
            '\\' => {
                i += 1;
                if i >= chars.len() {
                    return Err("Trailing backslash".to_string());
                }
            }
            _ => {}
        }
        i += 1;
    }
    if depth != 0 {
        return Err("Unmatched (".to_string());
    }
    Ok(())
}
