                if regex_match_dp(pat, atom_end + 1, text, ti) {
                    return true;
                }
                if ti < text.len() && matcher(text[ti]) {
                    return regex_match_dp(pat, atom_end + 1, text, ti + 1);
                }
                return false;
            }
            _ => {}
        }
    }

