        let alts = split_alternation(&group_pattern);

        let quant = if group_end < pat.len() {
            Some(pat[group_end])
        } else {
            None
        };

        match quant {
            Some('*') => {
                if regex_match_dp(pat, group_end + 1, text, ti) {
                    return true;
