                            }
                        }
                    }
                    if !advanced { break; }
                }
                return false;
            }
            Some('+') | Some('?') | None => {
                // Try each alternative
                for alt in &alts {
                    let alt_pat: Vec<char> = alt.chars().collect();
                    // Try to match alt at current position
                    for end in ti..=text.len() {
                        if try_match_exact(&alt_pat, &text[ti..end]) {
                            if quant == Some('?') {
                                if regex_match_dp(pat, group_end + 1, text, ti) {
                                    return true;
                                }
                                if regex_match_dp(pat, group_end + 1, text, end) {
                                    return true;
                                }
                            } else {
                                if regex_match_dp(pat, group_end + 1, text, end) {
                                    return true;
                                }
                            }
