cat > xsv_impl/src/cmd/cat.rs << 'RUST_EOF'
use std::process;
use crate::csv_core::{CsvConfig, CsvReader, CsvWriter, open_input, open_output};
use crate::util::Args;

const USAGE: &str = "
Concatenates CSV data by column or by row.

When concatenating by column, the columns will be written in the same order as
the inputs given. The number of rows in the result is always equivalent to to
the minimum number of rows across all given CSV data. (This behavior can be
reversed with the '--pad' flag.)

When concatenating by row, all CSV data must have the same number of columns.
If you need to rearrange the columns or fix the lengths of records, use the
'select' or 'fixlengths' commands. Also, only the headers of the *first* CSV
data given are used. Headers in subsequent inputs are ignored. (This behavior
can be disabled with --no-headers.)

Usage:
    xsv cat rows    [options] [<input>...]
    xsv cat columns [options] [<input>...]
    xsv cat --help

cat options:
    -p, --pad              When concatenating columns, this flag will cause
                           all records to appear. It will pad each row if
                           other CSV data isn't long enough.

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will NOT be interpreted
                           as column names. Note that this has no effect when
                           concatenating columns.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let pos = a.positional();

    if pos.is_empty() {
        eprintln!("Usage: xsv cat rows|columns [options] [<input>...]");
        process::exit(1);
    }

    let subcmd = &pos[0];
    let inputs: Vec<&str> = pos[1..].iter().map(|s| s.as_str()).collect();

    match subcmd.as_str() {
        "rows" => run_rows(args, &inputs),
        "columns" => run_columns(args, &inputs),
        _ => {
            eprintln!("Unknown cat subcommand: {}", subcmd);
            process::exit(1);
        }
    }
}

fn make_config(args: &[String]) -> (CsvConfig, bool) {
    let a = Args::new(args);
    let delimiter = a.delimiter();
    let no_headers = !a.has_headers();
    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };
    (config, no_headers)
}

fn run_rows(args: &[String], inputs: &[&str]) {
    let a = Args::new(args);
    let delimiter = a.delimiter();
    let no_headers = !a.has_headers();
    let output_path = a.output_path();

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });
    let mut writer = CsvWriter::new(output).with_delimiter(delimiter);

    let mut first = true;

    let input_list: Vec<Option<&str>> = if inputs.is_empty() {
        vec![None]
    } else {
        inputs.iter().map(|s| Some(*s)).collect()
    };

    for input_path in &input_list {
        let input = open_input(*input_path).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
        let mut reader = CsvReader::new(input, config.clone());
        let mut record = crate::csv_core::Record::new();

        if !no_headers {
            // Read header
            if !reader.read_record(&mut record).unwrap_or(false) {
                continue;
            }
            if first {
                // Write header from first file
                let refs: Vec<&[u8]> = record.fields.iter().map(|f| f.as_slice()).collect();
                writer.write_record(&refs).unwrap_or_else(|e| {
                    eprintln!("{}", e);
                    process::exit(1);
                });
                first = false;
            }
            // else skip headers from subsequent files
        }

        // Write data rows
        while reader.read_record(&mut record).unwrap_or(false) {
            let refs: Vec<&[u8]> = record.fields.iter().map(|f| f.as_slice()).collect();
            writer.write_record(&refs).unwrap_or_else(|e| {
                eprintln!("{}", e);
                process::exit(1);
            });
        }
    }

    writer.flush().ok();
}

fn run_columns(args: &[String], inputs: &[&str]) {
    let a = Args::new(args);
    let delimiter = a.delimiter();
    let pad = a.flag2("--pad", "-p");
    let output_path = a.output_path();

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input_list: Vec<Option<&str>> = if inputs.is_empty() {
        vec![None]
    } else {
        inputs.iter().map(|s| Some(*s)).collect()
    };

    // Read all data into memory
    let mut all_headers: Vec<Vec<Vec<u8>>> = Vec::new();
    let mut all_rows: Vec<Vec<Vec<Vec<u8>>>> = Vec::new();

    for input_path in &input_list {
        let input = open_input(*input_path).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
