use std::process;
use crate::csv_core::{CsvConfig, CsvReader, CsvWriter, open_input, open_output};
use crate::util::Args;

const USAGE: &str = "
Reverses rows of CSV data.

Useful for cases when there is no column that can be used for sorting in reverse order,
or when keys are not unique and order of rows with the same key needs to be preserved.

Note that this requires reading all of the CSV data into memory.

Usage:
    xsv reverse [options] [<input>]

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will not be interpreted
                           as headers. Namely, it will be reversed with the rest
                           of the rows. Otherwise, the first row will always
                           appear as the header row in the output.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let delimiter = a.delimiter();
    let no_headers = !a.has_headers();
    let output_path = a.output_path();

    let pos = a.positional();
    let input_path = pos.first().map(|s| s.as_str());

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });
    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut writer = CsvWriter::new(output).with_delimiter(delimiter);
    let mut record = crate::csv_core::Record::new();

    let mut header: Option<Vec<Vec<u8>>> = None;
    let mut rows: Vec<Vec<Vec<u8>>> = Vec::new();

    if !no_headers {
        if reader.read_record(&mut record).unwrap_or(false) {
            header = Some(record.fields.clone());
        }
    }

    while reader.read_record(&mut record).unwrap_or(false) {
        rows.push(record.fields.clone());
    }

    // Write header
    if let Some(h) = &header {
        let refs: Vec<&[u8]> = h.iter().map(|f| f.as_slice()).collect();
        writer.write_record(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    // Write rows in reverse
    for row in rows.iter().rev() {
        let refs: Vec<&[u8]> = row.iter().map(|f| f.as_slice()).collect();
        writer.write_record(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    writer.flush().ok();
}
