    let output_path = a.output_path();
    let select = a.opt2("--select", "-s");
    let numeric = a.flag2("--numeric", "-N");
    let reverse = a.flag2("--reverse", "-R");

    let pos = a.positional();
    let input_path = pos.first().map(|s| s.as_str());

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });
    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut writer = CsvWriter::new(output).with_delimiter(delimiter);
    let mut record = crate::csv_core::Record::new();

    let mut header: Option<Vec<Vec<u8>>> = None;
    let mut rows: Vec<Vec<Vec<u8>>> = Vec::new();

    let mut sort_indices: Option<Vec<usize>> = None;

    if !no_headers {
        if reader.read_record(&mut record).unwrap_or(false) {
            let hdrs = record.fields.clone();

            if let Some(sel_str) = select {
                let sel = Selection::parse(sel_str).unwrap_or_else(|e| {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                });
                let indices = sel.indices(&hdrs).unwrap_or_else(|e| {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                });
                sort_indices = Some(indices);
            }

            header = Some(hdrs);
        }
    } else {
        // Need to handle numeric headers for select
        // We'll determine after reading first row
    }

    while reader.read_record(&mut record).unwrap_or(false) {
        if no_headers && sort_indices.is_none() {
            if let Some(sel_str) = select {
                let n = record.len();
                let fake_headers: Vec<Vec<u8>> = (1..=n).map(|i| i.to_string().into_bytes()).collect();
                let sel = Selection::parse(sel_str).unwrap_or_else(|e| {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                });
                let indices = sel.indices(&fake_headers).unwrap_or_else(|e| {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                });
                sort_indices = Some(indices);
            }
        }
        rows.push(record.fields.clone());
    }

    // Sort rows
    rows.sort_by(|a, b| {
        let key_a = get_sort_key(a, &sort_indices);
        let key_b = get_sort_key(b, &sort_indices);

        let cmp = if numeric {
            compare_numeric(&key_a, &key_b)
        } else {
            key_a.cmp(&key_b)
        };

        if reverse { cmp.reverse() } else { cmp }
    });

    // Write header
    if let Some(h) = &header {
        let refs: Vec<&[u8]> = h.iter().map(|f| f.as_slice()).collect();
        writer.write_record(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    for row in &rows {
        let refs: Vec<&[u8]> = row.iter().map(|f| f.as_slice()).collect();
        writer.write_record(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    writer.flush().ok();
}

fn get_sort_key(row: &[Vec<u8>], indices: &Option<Vec<usize>>) -> Vec<Vec<u8>> {
    if let Some(idxs) = indices {
        idxs.iter().map(|&i| {
            row.get(i).cloned().unwrap_or_default()
        }).collect()
    } else {
        row.to_vec()
    }
}

fn compare_numeric(a: &[Vec<u8>], b: &[Vec<u8>]) -> std::cmp::Ordering {
    for (av, bv) in a.iter().zip(b.iter()) {
        let an = std::str::from_utf8(av).ok().and_then(|s| s.parse::<f64>().ok());
        let bn = std::str::from_utf8(bv).ok().and_then(|s| s.parse::<f64>().ok());

        let cmp = match (an, bn) {
            (Some(a), Some(b)) => a.partial_cmp(&b).unwrap_or(std::cmp::Ordering::Equal),
            (Some(_), None) => std::cmp::Ordering::Greater,
            (None, Some(_)) => std::cmp::Ordering::Less,
            (None, None) => av.cmp(bv),
        };
        if cmp != std::cmp::Ordering::Equal {
            return cmp;
        }
    }
    std::cmp::Ordering::Equal
}
