use std::process;
use std::collections::HashMap;
use crate::csv_core::{CsvConfig, CsvReader, CsvWriter, open_input, open_output};
use crate::util::Args;
use crate::select::Selection;

const USAGE: &str = "
Compute a frequency table on CSV data.

The frequency table is formatted as CSV data:

    field,value,count

By default, there is a row for the N most frequent values for each field in the
data. The order and number of values can be tweaked with --asc and --limit,
respectively.

Since this computes an exact frequency table, memory proportional to the
cardinality of each column is required.

Usage:
    xsv frequency [options] [<input>]

frequency options:
    -s, --select <arg>     Select a subset of columns to compute frequencies
                           for. See 'xsv select --help' for the format
                           details. This is provided here because piping 'xsv
                           select' into 'xsv frequency' will disable the use
                           of indexing.
    -l, --limit <arg>      Limit the frequency table to the N most common
                           items. Set to '0' to disable a limit.
                           [default: 10]
    -a, --asc              Sort the frequency tables in ascending order by
                           count. The default is descending order.
    --no-nulls             Don't include NULLs in the frequency table.
    -j, --jobs <arg>       The number of jobs to run in parallel.
                           This works better when the given CSV data has
                           an index already created. Note that a file handle
                           is opened for each job.
                           When set to '0', the number of jobs is set to the
                           number of CPUs detected.
                           [default: 0]

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will NOT be included
                           in the frequency table. Additionally, the 'field'
                           column will be 1-based indices instead of header
                           names.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let delimiter = a.delimiter();
    let no_headers = !a.has_headers();
    let output_path = a.output_path();
    let select = a.opt2("--select", "-s");
    let limit: usize = a.opt2("--limit", "-l")
        .and_then(|s| s.parse().ok())
        .unwrap_or(10);
    let asc = a.flag2("--asc", "-a");
    let no_nulls = a.flag("--no-nulls");

    let pos = a.positional();
    let input_path = pos.first().map(|s| s.as_str());

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });
    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut writer = CsvWriter::new(output).with_delimiter(b',');
    let mut record = crate::csv_core::Record::new();

    let mut field_names: Vec<String> = Vec::new();
    let mut select_indices: Option<Vec<usize>> = None;

    if !no_headers {
        if !reader.read_record(&mut record).unwrap_or(false) {
            // Empty file
            writer.write_record_from_strs(&["field", "value", "count"]).ok();
            writer.flush().ok();
            return;
        }
        field_names = record.fields.iter()
            .map(|f| String::from_utf8_lossy(f).into_owned())
            .collect();

        if let Some(sel_str) = select {
            let sel = Selection::parse(sel_str).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            let indices = sel.indices(&record.fields).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            select_indices = Some(indices);
        }
    }

    // Count frequencies
    let mut freq_maps: Vec<HashMap<String, u64>> = Vec::new();
    let mut first_row = true;

    while reader.read_record(&mut record).unwrap_or(false) {
        if first_row && no_headers {
            let n = record.len();
            field_names = (1..=n).map(|i| i.to_string()).collect();
            if let Some(sel_str) = select {
                let fake_headers: Vec<Vec<u8>> = (1..=n).map(|i| i.to_string().into_bytes()).collect();
                let sel = Selection::parse(sel_str).unwrap_or_else(|e| {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                });
                let indices = sel.indices(&fake_headers).unwrap_or_else(|e| {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                });
                select_indices = Some(indices);
            }
            first_row = false;
        } else {
            first_row = false;
        }

        if freq_maps.is_empty() {
            let n_fields = if let Some(ref idxs) = select_indices {
                idxs.len()
            } else {
                record.len()
            };
            freq_maps = vec![HashMap::new(); n_fields];
        }

        let fields: Vec<&[u8]> = if let Some(ref idxs) = select_indices {
            idxs.iter().map(|&i| record.get(i).unwrap_or(b"")).collect()
        } else {
            record.fields.iter().map(|f| f.as_slice()).collect()
        };

        for (i, field) in fields.iter().enumerate() {
            if i >= freq_maps.len() {
                freq_maps.resize(i + 1, HashMap::new());
            }
            let s = String::from_utf8_lossy(field).into_owned();
            if no_nulls && s.is_empty() {
                continue;
            }
            *freq_maps[i].entry(s).or_insert(0) += 1;
        }
    }

    // Write output
    writer.write_record_from_strs(&["field", "value", "count"]).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let col_names: Vec<String> = if let Some(ref idxs) = select_indices {
        idxs.iter().map(|&i| field_names.get(i).cloned().unwrap_or_else(|| i.to_string())).collect()
    } else {
        field_names.clone()
    };

    for (i, freq_map) in freq_maps.iter().enumerate() {
        let field_name = col_names.get(i).map(|s| s.as_str()).unwrap_or("");

        let mut entries: Vec<(&str, u64)> = freq_map.iter()
            .map(|(k, &v)| (k.as_str(), v))
            .collect();

        // Sort by count (desc or asc), then by value
        entries.sort_by(|a, b| {
            let count_cmp = if asc {
                a.1.cmp(&b.1)
            } else {
                b.1.cmp(&a.1)
            };
            if count_cmp == std::cmp::Ordering::Equal {
                a.0.cmp(b.0)
            } else {
                count_cmp
            }
        });

        let to_show = if limit == 0 {
            entries.len()
        } else {
            entries.len().min(limit)
        };

        for j in 0..to_show {
            let (val, count) = entries[j];
            let display_val = if val.is_empty() { "(NULL)" } else { val };
            writer.write_record_from_strs(&[field_name, display_val, &count.to_string()]).unwrap_or_else(|e| {
                eprintln!("{}", e);
                process::exit(1);
            });
        }
    }

    writer.flush().ok();
}
