use std::process;
use std::fs::File;
use crate::csv_core::{CsvConfig, CsvReader};
use crate::util::Args;

const USAGE: &str = "
Creates an index of the given CSV data, which can make other operations like
slicing, splitting and gathering statistics much faster.

Note that this does not accept CSV data on stdin. You must give a file
path. The index is created at 'path/to/input.csv.idx'. The index will be
automatically used by commands that can benefit from it. If the original CSV
data changes after the index is made, commands that try to use it will result
in an error (you have to regenerate the index before it can be used again).

Usage:
    xsv index [options] <input>
    xsv index --help

index options:
    -o, --output <file>    Write index to <file> instead of <input>.idx.
                           Generally, this is not currently useful because
                           the only way to use an index is if it is specially
                           named <input>.idx.

Common options:
    -h, --help             Display this message
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let delimiter = a.delimiter();
    let output_path = a.output_path();

    let pos = a.positional();

    if pos.is_empty() {
        eprintln!("Usage: xsv index [options] <input>");
        process::exit(1);
    }

    let input_path = &pos[0];

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let file = File::open(input_path).unwrap_or_else(|e| {
        eprintln!("failed to open {}: {}", input_path, e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(file, config);
    let mut record = crate::csv_core::Record::new();
    let mut offsets: Vec<u64> = Vec::new();
    let mut total_rows = 0u64;

    // Record offset before reading each row
    loop {
        let offset_before = reader.byte_offset();
        let ok = reader.read_record(&mut record).unwrap_or(false);
        if !ok {
            break;
        }
        offsets.push(offset_before);
        total_rows += 1;
    }

    let idx_path = output_path.unwrap_or_else(|| format!("{}.idx", input_path));

    // Write index
    let mut f = std::fs::File::create(&idx_path).unwrap_or_else(|e| {
        eprintln!("failed to create {}: {}", idx_path, e);
        process::exit(1);
    });

    use std::io::Write;
    for &offset in &offsets {
        f.write_all(&offset.to_be_bytes()).unwrap();
    }
    // Write total rows (including header = total_rows)
    f.write_all(&total_rows.to_be_bytes()).unwrap();

    f.flush().unwrap();
}
