            process::exit(1);
        });
    }

    let empty1: Vec<Vec<u8>> = vec![vec![]; headers1.len().max(if rows1.is_empty() { 0 } else { rows1[0].len() })];
    let empty2: Vec<Vec<u8>> = vec![vec![]; headers2.len().max(if rows2.is_empty() { 0 } else { rows2[0].len() })];

    if cross {
        // Cartesian product
        for row1 in &rows1 {
            for row2 in &rows2 {
                let combined: Vec<Vec<u8>> = row1.iter().chain(row2.iter()).cloned().collect();
                let refs: Vec<&[u8]> = combined.iter().map(|f| f.as_slice()).collect();
