use crate::select::Selection;

const USAGE: &str = "
Joins two sets of CSV data on the specified columns.

The default join operation is an 'inner' join. This corresponds to the
intersection of rows on the keys specified.

Joins are always done by ignoring leading and trailing whitespace. By default,
joins are done case sensitively, but this can be disabled with the --no-case
flag.

The columns arguments specify the columns to join for each input. Columns can
be referenced by name or index, starting at 1. Specify multiple columns by
separating them with a comma. Specify a range of columns with `-`. Both
columns1 and columns2 must specify exactly the same number of columns.
(See 'xsv select --help' for the full syntax.)

Usage:
    xsv join [options] <columns1> <input1> <columns2> <input2>
    xsv join --help

join options:
    --no-case              When set, joins are done case insensitively.
    --left                 Do a 'left outer' join. This returns all rows in
                           first CSV data set, including rows with no
                           corresponding row in the second data set. When no
                           corresponding row exists, it is padded out with
                           empty fields.
    --right                Do a 'right outer' join. This returns all rows in
                           second CSV data set, including rows with no
                           corresponding row in the first data set. When no
                           corresponding row exists, it is padded out with
                           empty fields. (This is the reverse of 'outer left'.)
    --full                 Do a 'full outer' join. This returns all rows in
                           both data sets with matching records joined. If
                           there is no match, the missing side will be padded
                           out with empty fields. (This is the combination of
                           'outer left' and 'outer right'.)
    --cross                USE WITH CAUTION.
                           This returns the cartesian product of the CSV
                           data sets given. The number of rows return is
                           equal to N * M, where N and M correspond to the
                           number of rows in the given data sets, respectively.
    --nulls                When set, joins will work on empty fields.
                           Otherwise, empty fields are completely ignored.
                           (In fact, any row that has an empty field in the
                           key specified is ignored.)

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will not be interpreted
                           as headers. (i.e., They are not searched, analyzed,
                           sliced, etc.)
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let delimiter = a.delimiter();
    let no_headers = !a.has_headers();
    let output_path = a.output_path();
    let no_case = a.flag("--no-case");
    let left = a.flag("--left");
    let right = a.flag("--right");
    let full = a.flag("--full");
    let cross = a.flag("--cross");
    let nulls = a.flag("--nulls");

    let pos = a.positional();

    if pos.len() < 4 {
        eprintln!("Usage: xsv join [options] <columns1> <input1> <columns2> <input2>");
        process::exit(1);
    }

    let cols1_str = &pos[0];
    let input1_path = &pos[1];
    let cols2_str = &pos[2];
    let input2_path = &pos[3];

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    // Read file 1
    let (headers1, rows1) = read_csv(input1_path, &config);
    // Read file 2
    let (headers2, rows2) = read_csv(input2_path, &config);

    // Get key indices
    let key1_indices = if no_headers {
        let fake: Vec<Vec<u8>> = (1..=rows1.get(0).map(|r| r.len()).unwrap_or(0))
            .map(|i| i.to_string().into_bytes()).collect();
        get_indices(cols1_str, &fake)
    } else {
        get_indices(cols1_str, &headers1)
    };

    let key2_indices = if no_headers {
        let fake: Vec<Vec<u8>> = (1..=rows2.get(0).map(|r| r.len()).unwrap_or(0))
            .map(|i| i.to_string().into_bytes()).collect();
        get_indices(cols2_str, &fake)
    } else {
        get_indices(cols2_str, &headers2)
    };

    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });
    let mut writer = CsvWriter::new(output).with_delimiter(delimiter);

    // Write combined headers
    if !no_headers {
        let combined: Vec<Vec<u8>> = headers1.iter().chain(headers2.iter()).cloned().collect();
        let refs: Vec<&[u8]> = combined.iter().map(|f| f.as_slice()).collect();
        writer.write_record(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    let empty1: Vec<Vec<u8>> = vec![vec![]; headers1.len().max(if rows1.is_empty() { 0 } else { rows1[0].len() })];
    let empty2: Vec<Vec<u8>> = vec![vec![]; headers2.len().max(if rows2.is_empty() { 0 } else { rows2[0].len() })];

    if cross {
        // Cartesian product
        for row1 in &rows1 {
            for row2 in &rows2 {
                let combined: Vec<Vec<u8>> = row1.iter().chain(row2.iter()).cloned().collect();
                let refs: Vec<&[u8]> = combined.iter().map(|f| f.as_slice()).collect();
                writer.write_record(&refs).unwrap_or_else(|e| {
                    eprintln!("{}", e);
                    process::exit(1);
                });
            }
        }
    } else {
        // Build hash index on file2 (or file1 for right join)
        let mut index2: HashMap<Vec<Vec<u8>>, Vec<usize>> = HashMap::new();

        for (i, row) in rows2.iter().enumerate() {
            let key = extract_key(row, &key2_indices, no_case, nulls);
            if let Some(k) = key {
                index2.entry(k).or_default().push(i);
            }
        }

        let mut matched2: Vec<bool> = vec![false; rows2.len()];

        // Process rows1
        for row1 in &rows1 {
            let key1 = extract_key(row1, &key1_indices, no_case, nulls);

            if let Some(ref k) = key1 {
                if let Some(matching) = index2.get(k) {
                    for &idx2 in matching {
                        matched2[idx2] = true;
                        let combined: Vec<Vec<u8>> = row1.iter().chain(rows2[idx2].iter()).cloned().collect();
                        let refs: Vec<&[u8]> = combined.iter().map(|f| f.as_slice()).collect();
                        writer.write_record(&refs).unwrap_or_else(|e| {
                            eprintln!("{}", e);
                            process::exit(1);
                        });
                    }
                } else if left || full {
                    // Left row with no match - pad right
                    let ncols2 = if rows2.is_empty() { headers2.len() } else { rows2[0].len() };
                    let pad: Vec<Vec<u8>> = vec![vec![]; ncols2];
                    let combined: Vec<Vec<u8>> = row1.iter().chain(pad.iter()).cloned().collect();
                    let refs: Vec<&[u8]> = combined.iter().map(|f| f.as_slice()).collect();
                    writer.write_record(&refs).unwrap_or_else(|e| {
                        eprintln!("{}", e);
                        process::exit(1);
                    });
                }
            } else if left || full {
                // Row with no key (empty key fields)
                let ncols2 = if rows2.is_empty() { headers2.len() } else { rows2[0].len() };
                let pad: Vec<Vec<u8>> = vec![vec![]; ncols2];
                let combined: Vec<Vec<u8>> = row1.iter().chain(pad.iter()).cloned().collect();
                let refs: Vec<&[u8]> = combined.iter().map(|f| f.as_slice()).collect();
                writer.write_record(&refs).unwrap_or_else(|e| {
                    eprintln!("{}", e);
                    process::exit(1);
                });
            }
        }

        // For right or full join, add unmatched rows from file2
        if right || full {
            for (i, row2) in rows2.iter().enumerate() {
                if !matched2[i] {
                    let ncols1 = if rows1.is_empty() { headers1.len() } else { rows1[0].len() };
                    let pad: Vec<Vec<u8>> = vec![vec![]; ncols1];
                    let combined: Vec<Vec<u8>> = pad.iter().chain(row2.iter()).cloned().collect();
                    let refs: Vec<&[u8]> = combined.iter().map(|f| f.as_slice()).collect();
                    writer.write_record(&refs).unwrap_or_else(|e| {
                        eprintln!("{}", e);
                        process::exit(1);
                    });
                }
            }
        }
    }

    writer.flush().ok();
}

fn read_csv(path: &str, config: &CsvConfig) -> (Vec<Vec<u8>>, Vec<Vec<Vec<u8>>>) {
    let input = open_input(Some(path)).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config.clone());
    let mut record = crate::csv_core::Record::new();

    let mut headers = Vec::new();
    let mut rows = Vec::new();

    if reader.read_record(&mut record).unwrap_or(false) {
        headers = record.fields.clone();
    }

    while reader.read_record(&mut record).unwrap_or(false) {
        rows.push(record.fields.clone());
    }

    (headers, rows)
}

fn get_indices(spec: &str, headers: &[Vec<u8>]) -> Vec<usize> {
    let sel = Selection::parse(spec).unwrap_or_else(|e| {
        eprintln!("Error parsing column spec: {}", e);
        process::exit(1);
    });
    sel.indices(headers).unwrap_or_else(|e| {
        eprintln!("Error: {}", e);
        process::exit(1);
    })
}

fn extract_key(row: &[Vec<u8>], indices: &[usize], no_case: bool, nulls: bool) -> Option<Vec<Vec<u8>>> {
    let mut key = Vec::new();
    for &i in indices {
        let val = row.get(i).cloned().unwrap_or_default();
        if !nulls && val.is_empty() {
            return None;
        }
        let val = if no_case {
            let s = String::from_utf8_lossy(&val).to_lowercase();
            s.into_bytes()
        } else {
            // Trim whitespace
            let s = String::from_utf8_lossy(&val);
            s.trim().as_bytes().to_vec()
        };
        key.push(val);
    }
    Some(key)
}
