use std::process;
use std::collections::HashMap;
use std::io::Write;
use crate::csv_core::{CsvConfig, CsvReader, CsvWriter, open_input};
use crate::util::Args;
use crate::select::Selection;

const USAGE: &str = "
Partitions the given CSV data into chunks based on the value of a column

The files are written to the output directory with filenames based on the
values in the partition column and the `--filename` flag.

Usage:
    xsv partition [options] <column> <outdir> [<input>]
    xsv partition --help

partition options:
    --filename <filename>  A filename template to use when constructing
                           the names of the output files.  The string '{}'
                           will be replaced by a value based on the value
                           of the field, but sanitized for shell safety.
                           [default: {}.csv]
    -p, --prefix-length <n>  Truncate the partition column after the
                           specified number of bytes when creating the
                           output file.
    --drop                 Drop the partition column from results.

Common options:
    -h, --help             Display this message
    -n, --no-headers       When set, the first row will NOT be interpreted
                           as column names. Otherwise, the first row will
                           appear in all chunks as the header row.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let delimiter = a.delimiter();
    let no_headers = !a.has_headers();
    let filename_template = a.opt("--filename").unwrap_or("{}.csv");
    let prefix_length: Option<usize> = a.opt2("--prefix-length", "-p")
        .and_then(|s| s.parse().ok());
    let drop_col = a.flag("--drop");

    let pos = a.positional();

    if pos.len() < 2 {
        eprintln!("Usage: xsv partition [options] <column> <outdir> [<input>]");
        process::exit(1);
    }

    let column_spec = &pos[0];
    let outdir = &pos[1];
    let input_path = pos.get(2).map(|s| s.as_str());

    // Create output directory
    std::fs::create_dir_all(outdir).unwrap_or_else(|e| {
        eprintln!("failed to create directory {}: {}", outdir, e);
        process::exit(1);
    });

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut record = crate::csv_core::Record::new();

    let mut headers: Vec<Vec<u8>> = Vec::new();
    let mut col_idx: usize = 0;

    if !no_headers {
        if !reader.read_record(&mut record).unwrap_or(false) {
            return;
        }
        headers = record.fields.clone();

        // Find column index
        let sel = Selection::parse(column_spec).unwrap_or_else(|e| {
            eprintln!("Error: {}", e);
            process::exit(1);
        });
        let indices = sel.indices(&headers).unwrap_or_else(|e| {
            eprintln!("Error: {}", e);
            process::exit(1);
        });
        col_idx = indices[0];
    }

    // Map from partition key -> writer
    let mut writers: HashMap<String, CsvWriter<std::fs::File>> = HashMap::new();
    let mut header_written: HashMap<String, bool> = HashMap::new();

    while reader.read_record(&mut record).unwrap_or(false) {
        if no_headers && headers.is_empty() {
            let n = record.len();
            headers = (1..=n).map(|i| i.to_string().into_bytes()).collect();
            let fake: Vec<Vec<u8>> = (1..=n).map(|i| i.to_string().into_bytes()).collect();
            let sel = Selection::parse(column_spec).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            let indices = sel.indices(&fake).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            col_idx = indices[0];
        }

        let val = record.get(col_idx).unwrap_or(b"");
        let val_str = String::from_utf8_lossy(val).into_owned();

        // Create partition key (sanitize + optional prefix truncation)
        let mut key = sanitize_filename(&val_str);
        if let Some(plen) = prefix_length {
            key = key.chars().take(plen).collect();
        }

        let filename = filename_template.replace("{}", &key);
        let filepath = format!("{}/{}", outdir, filename);

        if !writers.contains_key(&key) {
            let f = std::fs::File::create(&filepath).unwrap_or_else(|e| {
                eprintln!("failed to create {}: {}", filepath, e);
                process::exit(1);
            });
            let writer = CsvWriter::new(f).with_delimiter(delimiter);
            writers.insert(key.clone(), writer);
            header_written.insert(key.clone(), false);
        }

        let writer = writers.get_mut(&key).unwrap();

        // Write header if needed
        if !no_headers && !*header_written.get(&key).unwrap_or(&false) {
            let h_refs: Vec<Vec<u8>> = if drop_col {
                headers.iter().enumerate()
                    .filter(|(i, _)| *i != col_idx)
                    .map(|(_, f)| f.clone())
                    .collect()
            } else {
                headers.clone()
            };
            let refs: Vec<&[u8]> = h_refs.iter().map(|f| f.as_slice()).collect();
            writer.write_record(&refs).unwrap_or_else(|e| {
                eprintln!("{}", e);
                process::exit(1);
            });
            *header_written.get_mut(&key).unwrap() = true;
        }

        // Write record
        let row: Vec<Vec<u8>> = if drop_col {
            record.fields.iter().enumerate()
                .filter(|(i, _)| *i != col_idx)
                .map(|(_, f)| f.clone())
                .collect()
        } else {
            record.fields.clone()
        };

        let refs: Vec<&[u8]> = row.iter().map(|f| f.as_slice()).collect();
        writer.write_record(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    for (_, mut w) in writers {
        w.flush().ok();
    }
}

fn sanitize_filename(s: &str) -> String {
    s.chars().map(|c| {
        if c.is_alphanumeric() || c == '_' || c == '-' || c == '.' {
            c
        } else {
            '_'
        }
    }).collect()
}
