            m2: 0.0,
            values: Vec::new(),
            freq: HashMap::new(),
            first_min_length: true,
        }
    }

    fn update(&mut self, val: &str, use_nulls: bool, collect_all: bool) {
        self.total_count += 1;

        let len = val.chars().count(); // UTF-8 aware length? Actually byte length for min_length
        // Looking at tests: empty field has length 0, "30" has length 2
        let byte_len = val.len();

        if self.first_min_length {
            self.min_length = byte_len;
            self.first_min_length = false;
        } else if byte_len < self.min_length {
            self.min_length = byte_len;
        }
        if byte_len > self.max_length {
            self.max_length = byte_len;
        }

        if val.is_empty() {
            if use_nulls {
                // Count nulls in mean/stddev with value 0
                self.count += 1;
                // Welford update with x=0
                let x = 0.0f64;
                let delta = x - self.mean;
                self.mean += delta / self.count as f64;
                let delta2 = x - self.mean;
                self.m2 += delta * delta2;
            }
            return;
        }

        // Update type
        if self.field_type == FieldType::Null {
            if let Ok(i) = val.parse::<i64>() {
                self.field_type = FieldType::Integer;
            } else if val.parse::<f64>().is_ok() {
                self.field_type = FieldType::Float;
            } else {
                self.field_type = FieldType::Unicode;
            }
        } else if self.field_type == FieldType::Integer {
            if val.parse::<i64>().is_err() {
                if val.parse::<f64>().is_ok() {
                    self.field_type = FieldType::Float;
                } else {
                    self.field_type = FieldType::Unicode;
                }
            }
        } else if self.field_type == FieldType::Float {
            if val.parse::<f64>().is_err() {
                self.field_type = FieldType::Unicode;
            }
        }

        // Update min/max
        match &self.min {
            None => self.min = Some(val.to_string()),
            Some(m) => {
                if val < m.as_str() {
                    self.min = Some(val.to_string());
                }
            }
        }
        match &self.max {
            None => self.max = Some(val.to_string()),
            Some(m) => {
                if val > m.as_str() {
                    self.max = Some(val.to_string());
                }
            }
        }

        // Try to parse as number for sum/mean/stddev
        if let Ok(x) = val.parse::<f64>() {
            self.sum += x;
            self.count += 1;
            // Welford's algorithm
            let delta = x - self.mean;
            self.mean += delta / self.count as f64;
            let delta2 = x - self.mean;
            self.m2 += delta * delta2;
        }

