        if collect_all {
            *self.freq.entry(val.to_string()).or_insert(0) += 1;
            self.values.push(val.to_string());
        }
    }

    fn stddev(&self) -> f64 {
        if self.count < 2 {
            0.0
        } else {
            (self.m2 / self.count as f64).sqrt()
        }
    }

    fn median(&self) -> Option<f64> {
        if self.values.is_empty() {
            return None;
        }
        let mut nums: Vec<f64> = self.values.iter()
            .filter_map(|v| v.parse::<f64>().ok())
            .collect();
        if nums.is_empty() {
            return None;
        }
        nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let n = nums.len();
        if n % 2 == 0 {
            Some((nums[n/2 - 1] + nums[n/2]) / 2.0)
        } else {
