    let no_headers = !a.has_headers();
    let output_path = a.output_path();
    let select = a.opt2("--select", "-s");
    let everything = a.flag("--everything");
    let show_mode = everything || a.flag("--mode");
    let show_cardinality = everything || a.flag("--cardinality");
    let show_median = everything || a.flag("--median");
    let use_nulls = a.flag("--nulls");

    let collect_all = show_mode || show_cardinality || show_median;

    let pos = a.positional();
    let input_path = pos.first().map(|s| s.as_str());

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });
    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut writer = CsvWriter::new(output).with_delimiter(b',');
    let mut record = crate::csv_core::Record::new();

    let mut field_names: Vec<String> = Vec::new();
    let mut select_indices: Option<Vec<usize>> = None;
    let mut stats: Vec<ColumnStats> = Vec::new();

    if !no_headers {
        if !reader.read_record(&mut record).unwrap_or(false) {
            return;
        }
        field_names = record.fields.iter()
            .map(|f| String::from_utf8_lossy(f).into_owned())
            .collect();

        if let Some(sel_str) = select {
            let sel = Selection::parse(sel_str).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            let indices = sel.indices(&record.fields).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            select_indices = Some(indices);
        }
    }

    let mut first_row = true;

    while reader.read_record(&mut record).unwrap_or(false) {
        let fields: Vec<&[u8]> = if let Some(ref idxs) = select_indices {
            idxs.iter().map(|&i| record.get(i).unwrap_or(b"")).collect()
        } else {
            record.fields.iter().map(|f| f.as_slice()).collect()
        };

        if first_row {
            if no_headers {
                let n = if select_indices.is_some() { fields.len() } else { record.len() };
