                    let fake: Vec<Vec<u8>> = (1..=record.len()).map(|i| i.to_string().into_bytes()).collect();
                    let sel = Selection::parse(sel_str).unwrap_or_else(|e| {
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    });
                    let indices = sel.indices(&fake).unwrap_or_else(|e| {
                        eprintln!("Error: {}", e);
                        process::exit(1);
                    });
                    select_indices = Some(indices);
                }
            }
            first_row = false;

            let n_fields = if let Some(ref idxs) = select_indices {
                idxs.len()
            } else {
                record.len()
            };
            stats = (0..n_fields).map(|_| ColumnStats::new()).collect();
        }

        for (i, field) in fields.iter().enumerate() {
            if i >= stats.len() {
                stats.push(ColumnStats::new());
            }
            let s = std::str::from_utf8(field).unwrap_or("");
            stats[i].update(s, use_nulls, collect_all);
        }
    }

    // Write headers
    let mut header = vec!["field", "type", "sum", "min", "max", "min_length", "max_length", "mean", "stddev"];
    if show_median { header.push("median"); }
    if show_mode { header.push("mode"); }
    if show_cardinality { header.push("cardinality"); }

    writer.write_record_from_strs(&header).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    // Compute output field names
    let out_field_names: Vec<String> = if let Some(ref idxs) = select_indices {
        idxs.iter().map(|&i| field_names.get(i).cloned().unwrap_or_else(|| i.to_string())).collect()
    } else {
        field_names.clone()
    };

    for (i, stat) in stats.iter().enumerate() {
        let field_name = out_field_names.get(i).map(|s| s.as_str()).unwrap_or("");
        let type_str = match stat.field_type {
            FieldType::Null => "NULL",
            FieldType::Integer => "Integer",
            FieldType::Float => "Float",
            FieldType::Unicode => "Unicode",
        };

        let is_numeric = stat.field_type == FieldType::Integer || stat.field_type == FieldType::Float;

        let sum_str = if is_numeric {
            if stat.field_type == FieldType::Integer {
                (stat.sum as i64).to_string()
            } else {
                format_float(stat.sum)
            }
        } else {
            String::new()
        };

        let min_str = if is_numeric {
            stat.min.as_deref().unwrap_or("")
        } else {
            stat.min.as_deref().unwrap_or("")
        };
        let max_str = if is_numeric {
            stat.max.as_deref().unwrap_or("")
        } else {
            stat.max.as_deref().unwrap_or("")
        };

        let min_len_str = if stat.min_length == usize::MAX {
            "".to_string()
        } else {
            stat.min_length.to_string()
        };
        let max_len_str = stat.max_length.to_string();

        let mean_str = if is_numeric && stat.count > 0 {
            format_float(stat.mean)
        } else {
            String::new()
        };

        let stddev_str = if is_numeric && stat.count > 0 {
            format_float(stat.stddev())
        } else {
            String::new()
        };

        let mut row = vec![
            field_name.to_string(),
            type_str.to_string(),
            sum_str,
            min_str.to_string(),
            max_str.to_string(),
            min_len_str,
            max_len_str,
            mean_str,
            stddev_str,
        ];

        if show_median {
            let med_str = if is_numeric {
                stat.median().map(|v| format_float(v)).unwrap_or_default()
            } else {
                String::new()
            };
            row.push(med_str);
        }

        if show_mode {
            let mode_str = if is_numeric {
                stat.mode().unwrap_or_else(|| "N/A".to_string())
            } else if stat.field_type == FieldType::Unicode {
                // For Unicode, mode is the most common value
                if stat.freq.is_empty() {
                    "N/A".to_string()
                } else {
                    let max_count = *stat.freq.values().max().unwrap();
                    let modes: Vec<&String> = stat.freq.iter()
                        .filter(|(_, &v)| v == max_count)
                        .map(|(k, _)| k)
                        .collect();
                    if modes.len() > 1 {
                        "N/A".to_string()
                    } else {
                        modes.first().map(|s| (*s).clone()).unwrap_or_else(|| "N/A".to_string())
                    }
                }
            } else {
                "N/A".to_string()
            };
            row.push(mode_str);
        }

        if show_cardinality {
            let card_str = if stat.field_type != FieldType::Null {
                stat.cardinality().to_string()
            } else {
                String::new()
            };
            row.push(card_str);
        }

        let refs: Vec<&str> = row.iter().map(|s| s.as_str()).collect();
        writer.write_record_from_strs(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    writer.flush().ok();
}

