const USAGE: &str = "
Computes basic statistics on CSV data.

Basic statistics includes mean, median, mode, standard deviation, sum, max and
min values. Note that some statistics are expensive to compute, so they must
be enabled explicitly. By default, the following statistics are reported for
*every* column in the CSV data: mean, max, min and standard deviation. The
default set of statistics corresponds to statistics that can be computed
efficiently on a stream of data (i.e., constant memory).

Computing statistics on a large file can be made much faster if you create
an index for it first with 'xsv index'.

Usage:
    xsv stats [options] [<input>]

stats options:
    -s, --select <arg>     Select a subset of columns to compute stats for.
                           See 'xsv select --help' for the format details.
                           This is provided here because piping 'xsv select'
                           into 'xsv stats' will disable the use of indexing.
    --everything           Show all statistics available.
    --mode                 Show the mode.
                           This requires storing all CSV data in memory.
    --cardinality          Show the cardinality.
                           This requires storing all CSV data in memory.
    --median               Show the median.
                           This requires storing all CSV data in memory.
    --nulls                Include NULLs in the population size for computing
                           mean and standard deviation.
    -j, --jobs <arg>       The number of jobs to run in parallel.
                           This works better when the given CSV data has
                           an index already created. Note that a file handle
                           is opened for each job.
                           When set to '0', the number of jobs is set to the
                           number of CPUs detected.
                           [default: 0]

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will NOT be interpreted
                           as column names. i.e., They will be included
                           in statistics.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Debug, Clone, PartialEq)]
enum FieldType {
    Null,
    Integer,
    Float,
    Unicode,
}

struct ColumnStats {
    field_type: FieldType,
    sum: f64,
    min: Option<String>,
    max: Option<String>,
    min_length: usize,
    max_length: usize,
    count: u64,      // non-null count
    total_count: u64, // all rows count (for --nulls)
    // For Welford's algorithm
    mean: f64,
    m2: f64,
    // For median/mode/cardinality
    values: Vec<String>,
    freq: HashMap<String, u64>,
    first_min_length: bool,
}

impl ColumnStats {
    fn new() -> Self {
        ColumnStats {
            field_type: FieldType::Null,
            sum: 0.0,
            min: None,
            max: None,
            min_length: usize::MAX,
            max_length: 0,
            count: 0,
            total_count: 0,
            mean: 0.0,
            m2: 0.0,
            values: Vec::new(),
            freq: HashMap::new(),
            first_min_length: true,
        }
    }

    fn update(&mut self, val: &str, use_nulls: bool, collect_all: bool) {
        self.total_count += 1;

        let len = val.chars().count(); // UTF-8 aware length? Actually byte length for min_length
        // Looking at tests: empty field has length 0, "30" has length 2
        let byte_len = val.len();

        if self.first_min_length {
            self.min_length = byte_len;
            self.first_min_length = false;
        } else if byte_len < self.min_length {
            self.min_length = byte_len;
        }
        if byte_len > self.max_length {
            self.max_length = byte_len;
        }

        if val.is_empty() {
            if use_nulls {
                // Count nulls in mean/stddev with value 0
                self.count += 1;
                // Welford update with x=0
                let x = 0.0f64;
                let delta = x - self.mean;
                self.mean += delta / self.count as f64;
                let delta2 = x - self.mean;
                self.m2 += delta * delta2;
            }
            return;
        }

        // Update type
        if self.field_type == FieldType::Null {
            if let Ok(i) = val.parse::<i64>() {
                self.field_type = FieldType::Integer;
            } else if val.parse::<f64>().is_ok() {
                self.field_type = FieldType::Float;
            } else {
                self.field_type = FieldType::Unicode;
            }
        } else if self.field_type == FieldType::Integer {
            if val.parse::<i64>().is_err() {
                if val.parse::<f64>().is_ok() {
                    self.field_type = FieldType::Float;
                } else {
                    self.field_type = FieldType::Unicode;
                }
            }
        } else if self.field_type == FieldType::Float {
            if val.parse::<f64>().is_err() {
                self.field_type = FieldType::Unicode;
            }
        }

        // Update min/max
        match &self.min {
            None => self.min = Some(val.to_string()),
            Some(m) => {
                if val < m.as_str() {
                    self.min = Some(val.to_string());
                }
            }
        }
        match &self.max {
            None => self.max = Some(val.to_string()),
            Some(m) => {
                if val > m.as_str() {
                    self.max = Some(val.to_string());
                }
            }
        }

        // Try to parse as number for sum/mean/stddev
        if let Ok(x) = val.parse::<f64>() {
            self.sum += x;
            self.count += 1;
            // Welford's algorithm
            let delta = x - self.mean;
            self.mean += delta / self.count as f64;
            let delta2 = x - self.mean;
            self.m2 += delta * delta2;
        }

        // For mode/median/cardinality
        if collect_all {
            *self.freq.entry(val.to_string()).or_insert(0) += 1;
            self.values.push(val.to_string());
        }
    }

    fn stddev(&self) -> f64 {
        if self.count < 2 {
            0.0
        } else {
            (self.m2 / self.count as f64).sqrt()
        }
    }

    fn median(&self) -> Option<f64> {
        if self.values.is_empty() {
            return None;
        }
        let mut nums: Vec<f64> = self.values.iter()
            .filter_map(|v| v.parse::<f64>().ok())
            .collect();
        if nums.is_empty() {
            return None;
        }
        nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let n = nums.len();
        if n % 2 == 0 {
            Some((nums[n/2 - 1] + nums[n/2]) / 2.0)
        } else {
            Some(nums[n/2])
        }
    }

    fn mode(&self) -> Option<String> {
        if self.freq.is_empty() {
            return None;
        }
        // For numeric columns, check if there's a unique max count
        let max_count = *self.freq.values().max().unwrap();
        let modes: Vec<&String> = self.freq.iter()
            .filter(|(_, &v)| v == max_count)
            .map(|(k, _)| k)
            .collect();
        if modes.len() > 1 || max_count == 1 {
            None  // No unique mode
        } else {
            modes.first().map(|s| (*s).clone())
        }
    }

    fn cardinality(&self) -> usize {
        self.freq.len()
    }
}

