use std::process;
use std::collections::HashMap;
use crate::csv_core::{CsvConfig, CsvReader, CsvWriter, open_input, open_output};
use crate::util::Args;
use crate::select::Selection;

const USAGE: &str = "
Computes basic statistics on CSV data.

Basic statistics includes mean, median, mode, standard deviation, sum, max and
min values. Note that some statistics are expensive to compute, so they must
be enabled explicitly. By default, the following statistics are reported for
*every* column in the CSV data: mean, max, min and standard deviation. The
default set of statistics corresponds to statistics that can be computed
efficiently on a stream of data (i.e., constant memory).

Computing statistics on a large file can be made much faster if you create
an index for it first with 'xsv index'.

Usage:
    xsv stats [options] [<input>]

stats options:
    -s, --select <arg>     Select a subset of columns to compute stats for.
                           See 'xsv select --help' for the format details.
                           This is provided here because piping 'xsv select'
                           into 'xsv stats' will disable the use of indexing.
    --everything           Show all statistics available.
    --mode                 Show the mode.
                           This requires storing all CSV data in memory.
    --cardinality          Show the cardinality.
                           This requires storing all CSV data in memory.
    --median               Show the median.
                           This requires storing all CSV data in memory.
    --nulls                Include NULLs in the population size for computing
                           mean and standard deviation.
    -j, --jobs <arg>       The number of jobs to run in parallel.
                           This works better when the given CSV data has
                           an index already created. Note that a file handle
                           is opened for each job.
                           When set to '0', the number of jobs is set to the
                           number of CPUs detected.
                           [default: 0]

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will NOT be interpreted
                           as column names. i.e., They will be included
                           in statistics.
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

#[derive(Debug, Clone, PartialEq)]
enum FieldType {
    Null,
    Integer,
    Float,
    Unicode,
}

struct ColumnStats {
    field_type: FieldType,
    // Numeric stats
    sum: f64,
    min_num: f64,
    max_num: f64,
    has_num: bool,
    // String stats (for Unicode)
    min_str: Option<String>,
    max_str: Option<String>,
    // Length stats
    min_length: Option<usize>,
    max_length: usize,
    // Welford's algorithm for mean/variance
    count: u64,       // non-null numeric count
    total_count: u64, // all rows
    welf_n: u64,      // count for Welford (includes nulls as 0 if use_nulls)
    mean: f64,
    m2: f64,
    // For median/mode/cardinality
    values: Vec<f64>,  // numeric values for median
    freq: HashMap<String, u64>,  // string frequencies
}

impl ColumnStats {
    fn new() -> Self {
        ColumnStats {
            field_type: FieldType::Null,
            sum: 0.0,
            min_num: f64::INFINITY,
            max_num: f64::NEG_INFINITY,
            has_num: false,
            min_str: None,
            max_str: None,
            min_length: None,
            max_length: 0,
            count: 0,
            total_count: 0,
            welf_n: 0,
            mean: 0.0,
            m2: 0.0,
            values: Vec::new(),
            freq: HashMap::new(),
        }
    }

    fn update(&mut self, val: &str, use_nulls: bool, collect_all: bool) {
        self.total_count += 1;

        let byte_len = val.len();

        // Update length stats
        match self.min_length {
            None => self.min_length = Some(byte_len),
            Some(min) if byte_len < min => self.min_length = Some(byte_len),
            _ => {}
        }
        if byte_len > self.max_length {
            self.max_length = byte_len;
        }

        if collect_all {
            // Track frequency (including empty for cardinality)
            *self.freq.entry(val.to_string()).or_insert(0) += 1;
        }

        if val.is_empty() {
            if use_nulls {
                // Count null as 0 in Welford's
                self.welf_n += 1;
                let delta = 0.0 - self.mean;
                self.mean += delta / self.welf_n as f64;
                let delta2 = 0.0 - self.mean;
                self.m2 += delta * delta2;
            }
            return;
        }

        // Update type detection
        let try_int = val.parse::<i64>();
        let try_float = if try_int.is_err() { val.parse::<f64>() } else { Ok(0.0) };

        match self.field_type {
            FieldType::Null => {
                if try_int.is_ok() {
                    self.field_type = FieldType::Integer;
                } else if try_float.is_ok() || val.parse::<f64>().is_ok() {
                    self.field_type = FieldType::Float;
                } else {
                    self.field_type = FieldType::Unicode;
                }
            }
            FieldType::Integer => {
                if try_int.is_err() {
                    if val.parse::<f64>().is_ok() {
                        self.field_type = FieldType::Float;
                    } else {
                        self.field_type = FieldType::Unicode;
                    }
                }
            }
            FieldType::Float => {
                if val.parse::<f64>().is_err() {
                    self.field_type = FieldType::Unicode;
                }
            }
            FieldType::Unicode => {}
        }

        // Update string min/max (always, for Unicode use)
        match &self.min_str {
            None => self.min_str = Some(val.to_string()),
            Some(m) => {
                if val < m.as_str() {
                    self.min_str = Some(val.to_string());
                }
            }
        }
        match &self.max_str {
            None => self.max_str = Some(val.to_string()),
            Some(m) => {
                if val > m.as_str() {
                    self.max_str = Some(val.to_string());
                }
            }
        }

        // Try numeric update
        if let Ok(x) = val.parse::<f64>() {
            self.sum += x;
            self.count += 1;
            self.has_num = true;

            if x < self.min_num { self.min_num = x; }
            if x > self.max_num { self.max_num = x; }

            // Welford's
            self.welf_n += 1;
            let delta = x - self.mean;
            self.mean += delta / self.welf_n as f64;
            let delta2 = x - self.mean;
            self.m2 += delta * delta2;

            if collect_all {
                self.values.push(x);
            }
        }
    }

    fn stddev(&self) -> f64 {
        if self.welf_n < 2 {
            0.0
        } else {
            (self.m2 / self.welf_n as f64).sqrt()
        }
    }

    fn median(&self) -> Option<f64> {
        if self.values.is_empty() {
            return None;
        }
        let mut nums = self.values.clone();
        nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let n = nums.len();
        if n % 2 == 0 {
            Some((nums[n/2 - 1] + nums[n/2]) / 2.0)
        } else {
            Some(nums[n/2])
        }
    }

    fn mode_str(&self) -> String {
        if self.freq.is_empty() {
            return "N/A".to_string();
        }
        let max_count = *self.freq.values().max().unwrap();
        let modes: Vec<&String> = self.freq.iter()
            .filter(|(_, &v)| v == max_count)
            .map(|(k, _)| k)
            .collect();
        if modes.len() == 1 {
            modes[0].clone()
        } else {
            "N/A".to_string()
        }
    }

    fn cardinality(&self) -> usize {
        self.freq.len()
    }

    fn min_display(&self) -> String {
        match self.field_type {
            FieldType::Integer | FieldType::Float => {
                if self.has_num {
                    format!("{}", self.min_num)
                } else {
                    String::new()
                }
            }
            FieldType::Unicode => self.min_str.clone().unwrap_or_default(),
            FieldType::Null => String::new(),
        }
    }

    fn max_display(&self) -> String {
        match self.field_type {
            FieldType::Integer | FieldType::Float => {
                if self.has_num {
                    format!("{}", self.max_num)
                } else {
                    String::new()
                }
            }
            FieldType::Unicode => self.max_str.clone().unwrap_or_default(),
            FieldType::Null => String::new(),
        }
    }

    fn sum_display(&self) -> String {
        match self.field_type {
            FieldType::Integer => {
                if self.has_num {
                    format!("{}", self.sum as i64)
                } else {
                    String::new()
                }
            }
            FieldType::Float => {
                if self.has_num {
                    format!("{}", self.sum)
                } else {
                    String::new()
                }
            }
            _ => String::new(),
        }
    }
}

pub fn run(args: &[String]) {
    let a = Args::new(args);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let delimiter = a.delimiter();
    let no_headers = !a.has_headers();
    let output_path = a.output_path();
    let select = a.opt2("--select", "-s");
    let everything = a.flag("--everything");
    let show_mode = everything || a.flag("--mode");
    let show_cardinality = everything || a.flag("--cardinality");
    let show_median = everything || a.flag("--median");
    let use_nulls = a.flag("--nulls");

    let collect_all = show_mode || show_cardinality || show_median;

    let pos = a.positional();
    let input_path = pos.first().map(|s| s.as_str());

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });
    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut writer = CsvWriter::new(output).with_delimiter(b',');
    let mut record = crate::csv_core::Record::new();

    let mut field_names: Vec<String> = Vec::new();
    let mut select_indices: Option<Vec<usize>> = None;
    let mut stats: Vec<ColumnStats> = Vec::new();
    let mut initialized = false;

    if !no_headers {
        if !reader.read_record(&mut record).unwrap_or(false) {
            return;
        }
        field_names = record.fields.iter()
            .map(|f| String::from_utf8_lossy(f).into_owned())
            .collect();

        if let Some(sel_str) = select {
            let sel = Selection::parse(sel_str).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            let indices = sel.indices(&record.fields).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            let n = indices.len();
            select_indices = Some(indices);
            stats = (0..n).map(|_| ColumnStats::new()).collect();
            initialized = true;
        } else {
            let n = record.len();
            stats = (0..n).map(|_| ColumnStats::new()).collect();
            initialized = true;
        }
    }

    while reader.read_record(&mut record).unwrap_or(false) {
        if !initialized {
            // no_headers mode: determine field count from first row
            let n = record.len();
            field_names = (1..=n).map(|i| i.to_string()).collect();
            if let Some(sel_str) = select {
                let fake: Vec<Vec<u8>> = (1..=n).map(|i| i.to_string().into_bytes()).collect();
                let sel = Selection::parse(sel_str).unwrap_or_else(|e| {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                });
                let indices = sel.indices(&fake).unwrap_or_else(|e| {
                    eprintln!("Error: {}", e);
                    process::exit(1);
                });
                let m = indices.len();
                select_indices = Some(indices);
                stats = (0..m).map(|_| ColumnStats::new()).collect();
            } else {
                stats = (0..n).map(|_| ColumnStats::new()).collect();
            }
            initialized = true;
        }

        let fields: Vec<&[u8]> = if let Some(ref idxs) = select_indices {
            idxs.iter().map(|&i| record.get(i).unwrap_or(b"")).collect()
        } else {
            record.fields.iter().map(|f| f.as_slice()).collect()
        };

        for (i, field) in fields.iter().enumerate() {
            if i < stats.len() {
                let s = std::str::from_utf8(field).unwrap_or("");
                stats[i].update(s, use_nulls, collect_all);
            }
        }
    }

    // Write headers
    let mut header = vec!["field", "type", "sum", "min", "max", "min_length", "max_length", "mean", "stddev"];
    if show_median { header.push("median"); }
    if show_mode { header.push("mode"); }
    if show_cardinality { header.push("cardinality"); }

    writer.write_record_from_strs(&header).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    // Compute output field names
    let out_field_names: Vec<String> = if let Some(ref idxs) = select_indices {
        idxs.iter().map(|&i| field_names.get(i).cloned().unwrap_or_else(|| i.to_string())).collect()
    } else {
        field_names.clone()
    };

    for (i, stat) in stats.iter().enumerate() {
        let field_name = out_field_names.get(i).map(|s| s.as_str()).unwrap_or("");
        let type_str = match stat.field_type {
            FieldType::Null => "NULL",
            FieldType::Integer => "Integer",
            FieldType::Float => "Float",
            FieldType::Unicode => "Unicode",
        };

        let is_numeric = stat.field_type == FieldType::Integer || stat.field_type == FieldType::Float;

        let sum_str = stat.sum_display();
        let min_str = stat.min_display();
        let max_str = stat.max_display();

        let min_len_str = stat.min_length.map(|l| l.to_string()).unwrap_or_default();
        let max_len_str = stat.max_length.to_string();

        let mean_str = if is_numeric && stat.welf_n > 0 {
            format!("{}", stat.mean)
        } else {
            String::new()
        };

        let stddev_str = if is_numeric && stat.welf_n > 0 {
            format!("{}", stat.stddev())
        } else {
            String::new()
        };

        let mut row = vec![
            field_name.to_string(),
            type_str.to_string(),
            sum_str,
            min_str,
            max_str,
            min_len_str,
            max_len_str,
            mean_str,
            stddev_str,
        ];

        if show_median {
            let med_str = if is_numeric {
                stat.median().map(|v| format!("{}", v)).unwrap_or_default()
            } else {
                String::new()
            };
            row.push(med_str);
        }

        if show_mode {
            let mode_str = if stat.field_type == FieldType::Null {
                "N/A".to_string()
            } else {
                stat.mode_str()
            };
            row.push(mode_str);
        }

        if show_cardinality {
            let card_str = if stat.field_type != FieldType::Null {
                stat.cardinality().to_string()
            } else {
                String::new()
            };
            row.push(card_str);
        }

        let refs: Vec<&str> = row.iter().map(|s| s.as_str()).collect();
        writer.write_record_from_strs(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    writer.flush().ok();
}
