use std::process;
use crate::csv_core::{CsvConfig, CsvReader, CsvWriter, open_input, open_output, parse_delimiter};

pub struct Args {
    args: Vec<String>,
    // Options that take values (long and short forms)
    value_opts: Vec<String>,
}

impl Args {
    pub fn new_with_opts(args: &[String], value_opts: &[&str]) -> Self {
        let mut vops = vec![
            "--delimiter".to_string(), "-d".to_string(),
            "--output".to_string(), "-o".to_string(),
        ];
        for opt in value_opts {
            vops.push(opt.to_string());
        }
        Args {
            args: args.to_vec(),
            value_opts: vops,
        }
    }

    pub fn new(args: &[String]) -> Self {
        Args::new_with_opts(args, &[])
    }

    pub fn flag(&self, long: &str) -> bool {
        self.flag2(long, "")
    }

    pub fn flag2(&self, long: &str, short: &str) -> bool {
        self.args.iter().any(|a| {
            let matches_long = a == long;
            let matches_short = !short.is_empty() && a == short;
            // Make sure it's not being used as a value for a previous option
            matches_long || matches_short
        })
    }

    pub fn opt(&self, long: &str) -> Option<&str> {
        self.opt2(long, "")
    }

    pub fn opt2(&self, long: &str, short: &str) -> Option<&str> {
        for i in 0..self.args.len() {
            let a = &self.args[i];
            if (a == long || (!short.is_empty() && a == short)) && i + 1 < self.args.len() {
                return Some(&self.args[i + 1]);
            }
        }
        None
    }

    pub fn positional(&self) -> Vec<String> {
        let mut result = Vec::new();
        let mut i = 0;

        while i < self.args.len() {
            let a = &self.args[i];
            if a == "--" {
                i += 1;
                while i < self.args.len() {
                    result.push(self.args[i].clone());
                    i += 1;
                }
                break;
            } else if a.starts_with('-') && a.len() > 1 && a.as_str() != "-" {
                if self.value_opts.contains(a) {
                    i += 2; // skip option and its value
                } else {
                    i += 1; // skip flag
                }
            } else {
                result.push(a.clone());
                i += 1;
            }
        }
        result
    }

    pub fn delimiter(&self) -> u8 {
        self.opt2("--delimiter", "-d")
            .map(|s| parse_delimiter(s).unwrap_or_else(|e| { eprintln!("{}", e); process::exit(1); }))
            .unwrap_or(b',')
    }

    pub fn output_path(&self) -> Option<String> {
        self.opt2("--output", "-o").map(|s| s.to_string())
    }

    pub fn has_headers(&self) -> bool {
        !self.flag2("--no-headers", "-n")
    }

    pub fn input_config(&self) -> CsvConfig {
        CsvConfig {
            delimiter: self.delimiter(),
            quote: b'"',
            escape: None,
            no_quoting: false,
            has_headers: self.has_headers(),
        }
    }
}

pub fn make_reader(path: Option<&str>, config: CsvConfig) -> CsvReader<Box<dyn std::io::Read>> {
    let input = open_input(path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });
    CsvReader::new(input, config)
}

pub fn make_writer(path: Option<&str>) -> CsvWriter<Box<dyn std::io::Write>> {
    let output = open_output(path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });
    CsvWriter::new(output)
}

pub fn err_exit(msg: &str) -> ! {
    eprintln!("{}", msg);
    process::exit(1);
}

pub fn io_err_exit(e: std::io::Error) -> ! {
    eprintln!("{}", e);
    process::exit(1);
}

// Per-command Args constructors
pub fn args_for_command(args: &[String], value_opts: &[&str]) -> Args {
    Args::new_with_opts(args, value_opts)
}
