    }
}

fn try_match_alt_min(alt: &[char], text: &[char], start: usize) -> Option<usize> {
    // Try smallest match first
    for end in start..=text.len() {
        if match_dp_exact(alt, 0, text, start, end) {
            return Some(end);
        }
    }
    None
}

fn match_dp_exact(pat: &[char], pi: usize, text: &[char], start: usize, end: usize) -> bool {
    // Match pattern against text[start..end] exactly
