enum Atom {
    Literal(char),
    Dot,
    Class(Vec<ClassItem>, bool),
    Digit,
    NonDigit,
    Word,
    NonWord,
    Space,
    NonSpace,
}

impl Atom {
    fn matches(&self, c: char) -> bool {
        match self {
            Atom::Literal(ch) => c == *ch,
            Atom::Dot => c != '\n',
            Atom::Class(items, negated) => {
                let in_class = items.iter().any(|item| match item {
                    ClassItem::Single(ch) => c == *ch,
                    ClassItem::Range(a, b) => c >= *a && c <= *b,
                });
                if *negated { !in_class } else { in_class }
            }
            Atom::Digit => c.is_ascii_digit(),
            Atom::NonDigit => !c.is_ascii_digit(),
            Atom::Word => c.is_alphanumeric() || c == '_',
            Atom::NonWord => !(c.is_alphanumeric() || c == '_'),
            Atom::Space => c.is_whitespace(),
            Atom::NonSpace => !c.is_whitespace(),
        }
    }
}

#[derive(Debug, Clone)]
enum Quantifier {
    One,
    ZeroOrOne,
    ZeroOrMore,
    OneOrMore,
    Exactly(usize),
    AtLeast(usize),
    Between(usize, usize),
}

fn get_atom(pat: &[char], pi: usize) -> (usize, Atom) {
    if pi >= pat.len() {
        return (0, Atom::Dot);
    }
    match pat[pi] {
        '.' => (1, Atom::Dot),
        '\\' if pi + 1 < pat.len() => {
            let atom = match pat[pi + 1] {
                'd' => Atom::Digit,
                'D' => Atom::NonDigit,
                'w' => Atom::Word,
                'W' => Atom::NonWord,
                's' => Atom::Space,
                'S' => Atom::NonSpace,
                c => Atom::Literal(c),
            };
            (2, atom)
        }
        '[' => {
            let (end, items, negated) = parse_char_class(pat, pi);
            (end - pi, Atom::Class(items, negated))
        }
        c => (1, Atom::Literal(c)),
    }
}

fn parse_char_class(pat: &[char], pi: usize) -> (usize, Vec<ClassItem>, bool) {
    let mut i = pi + 1;
    let negated = if i < pat.len() && pat[i] == '^' {
        i += 1;
        true
    } else {
        false
    };

    let mut items = Vec::new();
    // Handle ] as first char inside class
    if i < pat.len() && pat[i] == ']' {
        items.push(ClassItem::Single(']'));
        i += 1;
    }

    while i < pat.len() && pat[i] != ']' {
        if i + 2 < pat.len() && pat[i + 1] == '-' && pat[i + 2] != ']' {
            items.push(ClassItem::Range(pat[i], pat[i + 2]));
            i += 3;
        } else if pat[i] == '\\' && i + 1 < pat.len() {
            items.push(ClassItem::Single(pat[i + 1]));
            i += 2;
        } else {
            items.push(ClassItem::Single(pat[i]));
            i += 1;
        }
    }

    (i + 1, items, negated)
}

fn get_quantifier(pat: &[char], pi: usize) -> (Quantifier, usize) {
    if pi >= pat.len() {
        return (Quantifier::One, pi);
    }
    match pat[pi] {
        '?' => (Quantifier::ZeroOrOne, pi + 1),
        '*' => (Quantifier::ZeroOrMore, pi + 1),
        '+' => (Quantifier::OneOrMore, pi + 1),
        '{' => {
            // Parse {n}, {n,}, {n,m}
            let mut i = pi + 1;
            let mut n_str = String::new();
            while i < pat.len() && pat[i].is_ascii_digit() {
                n_str.push(pat[i]);
                i += 1;
            }
            if n_str.is_empty() {
                return (Quantifier::One, pi);
            }
            let n: usize = n_str.parse().unwrap_or(0);
            if i < pat.len() && pat[i] == '}' {
                return (Quantifier::Exactly(n), i + 1);
            }
            if i < pat.len() && pat[i] == ',' {
                i += 1;
                let mut m_str = String::new();
                while i < pat.len() && pat[i].is_ascii_digit() {
                    m_str.push(pat[i]);
                    i += 1;
                }
                if i < pat.len() && pat[i] == '}' {
                    if m_str.is_empty() {
                        return (Quantifier::AtLeast(n), i + 1);
                    } else {
                        let m: usize = m_str.parse().unwrap_or(0);
                        return (Quantifier::Between(n, m), i + 1);
                    }
                }
            }
            (Quantifier::One, pi)
        }
        _ => (Quantifier::One, pi),
    }
}

fn find_group_end(pat: &[char], pi: usize) -> (usize, Vec<char>) {
    // pi points to '('
    let mut i = pi + 1;
    let mut depth = 1usize;
    let mut content = Vec::new();
    while i < pat.len() {
        match pat[i] {
            '(' => { depth += 1; content.push(pat[i]); }
            ')' => {
                depth -= 1;
                if depth == 0 {
                    return (i + 1, content);
                }
                content.push(pat[i]);
            }
            '\\' if i + 1 < pat.len() => {
                content.push(pat[i]);
                content.push(pat[i + 1]);
                i += 1;
            }
            c => content.push(c),
        }
        i += 1;
    }
    (i, content)
}

fn split_alt(content: &[char]) -> Vec<Vec<char>> {
    let mut alts: Vec<Vec<char>> = Vec::new();
    let mut current = Vec::new();
    let mut depth = 0usize;
    let mut i = 0;
    while i < content.len() {
        match content[i] {
            '(' => { depth += 1; current.push(content[i]); }
            ')' => { depth -= 1; current.push(content[i]); }
            '|' if depth == 0 => {
                alts.push(current.clone());
                current.clear();
            }
            '\\' if i + 1 < content.len() => {
                current.push(content[i]);
                current.push(content[i + 1]);
                i += 1;
            }
            c => current.push(c),
        }
        i += 1;
    }
    alts.push(current);
    alts
}
