    // Handle groups with alternation: (...|...)
    if pat[pi] == '(' {
        let (group_end, group_content) = find_group_end(pat, pi);
        // group_end points past the ')'

        let (quant, quant_end) = get_quantifier(pat, group_end);
        let alts = split_alt(&group_content);

        return try_alternatives(pat, quant, quant_end, &alts, text, ti);
    }

    // Get atom
    let (atom_len, atom) = get_atom(pat, pi);
    if atom_len == 0 {
        return true; // shouldn't happen
    }

    let (quant, quant_end) = get_quantifier(pat, pi + atom_len);
    let next_pi = quant_end;

    match quant {
        Quantifier::One => {
            if ti < text.len() && atom.matches(text[ti]) {
                match_dp(pat, next_pi, text, ti + 1)
            } else {
                false
            }
        }
        Quantifier::ZeroOrOne => {
            if match_dp(pat, next_pi, text, ti) { return true; }
            if ti < text.len() && atom.matches(text[ti]) {
                match_dp(pat, next_pi, text, ti + 1)
            } else {
                false
            }
        }
        Quantifier::ZeroOrMore => {
            if match_dp(pat, next_pi, text, ti) { return true; }
            let mut cur = ti;
            while cur < text.len() && atom.matches(text[cur]) {
                cur += 1;
                if match_dp(pat, next_pi, text, cur) { return true; }
            }
            false
        }
        Quantifier::OneOrMore => {
            if ti >= text.len() || !atom.matches(text[ti]) { return false; }
            let mut cur = ti + 1;
            if match_dp(pat, next_pi, text, cur) { return true; }
            while cur < text.len() && atom.matches(text[cur]) {
                cur += 1;
                if match_dp(pat, next_pi, text, cur) { return true; }
            }
            false
        }
        Quantifier::Exactly(n) => {
            let mut cur = ti;
            for _ in 0..n {
                if cur >= text.len() || !atom.matches(text[cur]) { return false; }
                cur += 1;
            }
            match_dp(pat, next_pi, text, cur)
        }
        Quantifier::AtLeast(n) => {
            let mut cur = ti;
            for _ in 0..n {
                if cur >= text.len() || !atom.matches(text[cur]) { return false; }
                cur += 1;
            }
            if match_dp(pat, next_pi, text, cur) { return true; }
            while cur < text.len() && atom.matches(text[cur]) {
                cur += 1;
                if match_dp(pat, next_pi, text, cur) { return true; }
            }
            false
        }
        Quantifier::Between(n, m) => {
            let mut cur = ti;
            for _ in 0..n {
                if cur >= text.len() || !atom.matches(text[cur]) { return false; }
                cur += 1;
            }
            if match_dp(pat, next_pi, text, cur) { return true; }
            let mut count = n;
            while count < m && cur < text.len() && atom.matches(text[cur]) {
                cur += 1;
                count += 1;
                if match_dp(pat, next_pi, text, cur) { return true; }
            }
            false
        }
    }
}

fn try_alternatives(pat: &[char], quant: Quantifier, next_pi: usize, alts: &[Vec<char>], text: &[char], ti: usize) -> bool {
    match quant {
        Quantifier::One => {
            for alt in alts {
                // Try to match alt starting at ti, then continue with rest of pattern
                if let Some(new_ti) = try_match_alt(alt, text, ti) {
                    if match_dp(pat, next_pi, text, new_ti) {
                        return true;
                    }
                }
            }
            false
        }
        Quantifier::ZeroOrOne => {
            if match_dp(pat, next_pi, text, ti) { return true; }
            for alt in alts {
                if let Some(new_ti) = try_match_alt(alt, text, ti) {
                    if match_dp(pat, next_pi, text, new_ti) {
                        return true;
                    }
                }
            }
            false
        }
        Quantifier::ZeroOrMore => {
            if match_dp(pat, next_pi, text, ti) { return true; }
            // Try matching group once or more
            let mut cur = ti;
            loop {
                let mut any = false;
                for alt in alts {
                    if let Some(new_ti) = try_match_alt_min(alt, text, cur) {
                        if new_ti > cur {
                            cur = new_ti;
                            any = true;
                            if match_dp(pat, next_pi, text, cur) {
                                return true;
                            }
                            break;
                        }
                    }
                }
                if !any { break; }
            }
            false
        }
        Quantifier::OneOrMore => {
            let mut cur = ti;
            let mut matched_once = false;
            loop {
                let mut any = false;
                for alt in alts {
                    if let Some(new_ti) = try_match_alt_min(alt, text, cur) {
                        if new_ti > cur {
                            cur = new_ti;
                            any = true;
                            matched_once = true;
                            if match_dp(pat, next_pi, text, cur) {
                                return true;
                            }
                            break;
                        }
                    }
                }
                if !any { break; }
            }
            false
        }
        _ => {
            // For other quantifiers, fall back to basic handling
            for alt in alts {
                if let Some(new_ti) = try_match_alt(alt, text, ti) {
                    if match_dp(pat, next_pi, text, new_ti) {
                        return true;
                    }
                }
            }
            false
        }
    }
}

fn try_match_alt(alt: &[char], text: &[char], start: usize) -> Option<usize> {
    // Try to match alt starting at start, return ending position if successful
    if match_dp(alt, 0, text, start) {
        // Find out how far it consumed - this is tricky without tracking
        // For now, try all lengths
        for end in (start..=text.len()).rev() {
            if match_dp_exact(alt, 0, text, start, end) {
                return Some(end);
            }
        }
        None
    } else {
        None
    }
}

fn try_match_alt_min(alt: &[char], text: &[char], start: usize) -> Option<usize> {
    // Try smallest match first
    for end in start..=text.len() {
        if match_dp_exact(alt, 0, text, start, end) {
            return Some(end);
        }
    }
    None
}

fn match_dp_exact(pat: &[char], pi: usize, text: &[char], start: usize, end: usize) -> bool {
    // Match pattern against text[start..end] exactly
    let slice = &text[start..end];
    // Create extended text with sentinel
    let mut extended = slice.to_vec();
    // Use match_at starting at 0 in the slice
    match_exact(pat, pi, slice, 0)
}

fn match_exact(pat: &[char], pi: usize, text: &[char], ti: usize) -> bool {
    if pi >= pat.len() {
        return ti >= text.len();
    }
    if ti > text.len() {
        return false;
    }

    if pat[pi] == '$' && pi == pat.len() - 1 {
        return ti >= text.len();
    }

    if pat[pi] == '(' {
        let (group_end, group_content) = find_group_end(pat, pi);
        let (quant, quant_end) = get_quantifier(pat, group_end);
        let alts = split_alt(&group_content);

        match quant {
            Quantifier::One => {
                for alt in &alts {
                    for end in ti..=text.len() {
                        if match_exact(alt, 0, text, ti) && end == ti + count_match(alt, text, ti) {
                            if match_exact(pat, quant_end, text, end) {
                                return true;
                            }
                        }
                        // simpler: try all end positions
                        if match_exact_segment(alt, text, ti, end) {
                            if match_exact(pat, quant_end, text, end) {
                                return true;
                            }
                        }
                    }
                }
                return false;
            }
            _ => {
                // Simplified
                for alt in &alts {
                    for end in ti..=text.len() {
                        if match_exact_segment(alt, text, ti, end) {
                            if match_exact(pat, quant_end, text, end) {
                                return true;
                            }
                        }
                    }
                }
                return false;
            }
        }
    }

    let (atom_len, atom) = get_atom(pat, pi);
    if atom_len == 0 { return true; }
    let (quant, quant_end) = get_quantifier(pat, pi + atom_len);

    match quant {
        Quantifier::One => {
            if ti < text.len() && atom.matches(text[ti]) {
                match_exact(pat, quant_end, text, ti + 1)
            } else {
                false
            }
        }
        Quantifier::ZeroOrOne => {
            if match_exact(pat, quant_end, text, ti) { return true; }
            if ti < text.len() && atom.matches(text[ti]) {
                match_exact(pat, quant_end, text, ti + 1)
            } else {
                false
            }
        }
        Quantifier::ZeroOrMore => {
            if match_exact(pat, quant_end, text, ti) { return true; }
            let mut cur = ti;
            while cur < text.len() && atom.matches(text[cur]) {
                cur += 1;
                if match_exact(pat, quant_end, text, cur) { return true; }
            }
            false
        }
        Quantifier::OneOrMore => {
            if ti >= text.len() || !atom.matches(text[ti]) { return false; }
            let mut cur = ti + 1;
            if match_exact(pat, quant_end, text, cur) { return true; }
            while cur < text.len() && atom.matches(text[cur]) {
                cur += 1;
                if match_exact(pat, quant_end, text, cur) { return true; }
            }
            false
        }
        _ => {
            false // simplified
        }
    }
}

fn match_exact_segment(pat: &[char], text: &[char], start: usize, end: usize) -> bool {
    let slice = &text[start..end];
    match_exact(pat, 0, slice, 0)
}

fn count_match(pat: &[char], text: &[char], start: usize) -> usize {
    for end in (start..=text.len()).rev() {
        if match_exact_segment(pat, text, start, end) {
            return end - start;
        }
    }
    0
}

enum Atom {
    Literal(char),
    Dot,
    Class(Vec<ClassItem>, bool),
    Digit,
    NonDigit,
    Word,
    NonWord,
    Space,
    NonSpace,
}

impl Atom {
    fn matches(&self, c: char) -> bool {
        match self {
            Atom::Literal(ch) => c == *ch,
            Atom::Dot => c != '\n',
            Atom::Class(items, negated) => {
                let in_class = items.iter().any(|item| match item {
                    ClassItem::Single(ch) => c == *ch,
                    ClassItem::Range(a, b) => c >= *a && c <= *b,
                });
                if *negated { !in_class } else { in_class }
            }
            Atom::Digit => c.is_ascii_digit(),
            Atom::NonDigit => !c.is_ascii_digit(),
            Atom::Word => c.is_alphanumeric() || c == '_',
            Atom::NonWord => !(c.is_alphanumeric() || c == '_'),
            Atom::Space => c.is_whitespace(),
            Atom::NonSpace => !c.is_whitespace(),
        }
    }
}

#[derive(Debug, Clone)]
enum Quantifier {
    One,
    ZeroOrOne,
    ZeroOrMore,
    OneOrMore,
    Exactly(usize),
    AtLeast(usize),
    Between(usize, usize),
}

fn get_atom(pat: &[char], pi: usize) -> (usize, Atom) {
    if pi >= pat.len() {
        return (0, Atom::Dot);
    }
    match pat[pi] {
        '.' => (1, Atom::Dot),
        '\\' if pi + 1 < pat.len() => {
            let atom = match pat[pi + 1] {
                'd' => Atom::Digit,
                'D' => Atom::NonDigit,
                'w' => Atom::Word,
                'W' => Atom::NonWord,
                's' => Atom::Space,
                'S' => Atom::NonSpace,
                c => Atom::Literal(c),
            };
            (2, atom)
        }
        '[' => {
            let (end, items, negated) = parse_char_class(pat, pi);
            (end - pi, Atom::Class(items, negated))
        }
        c => (1, Atom::Literal(c)),
    }
}

fn parse_char_class(pat: &[char], pi: usize) -> (usize, Vec<ClassItem>, bool) {
    let mut i = pi + 1;
    let negated = if i < pat.len() && pat[i] == '^' {
        i += 1;
        true
    } else {
        false
    };

    let mut items = Vec::new();
    // Handle ] as first char inside class
    if i < pat.len() && pat[i] == ']' {
        items.push(ClassItem::Single(']'));
        i += 1;
    }

    while i < pat.len() && pat[i] != ']' {
        if i + 2 < pat.len() && pat[i + 1] == '-' && pat[i + 2] != ']' {
            items.push(ClassItem::Range(pat[i], pat[i + 2]));
            i += 3;
        } else if pat[i] == '\\' && i + 1 < pat.len() {
            items.push(ClassItem::Single(pat[i + 1]));
            i += 2;
        } else {
            items.push(ClassItem::Single(pat[i]));
            i += 1;
        }
    }

    (i + 1, items, negated)
}

fn get_quantifier(pat: &[char], pi: usize) -> (Quantifier, usize) {
    if pi >= pat.len() {
        return (Quantifier::One, pi);
    }
    match pat[pi] {
        '?' => (Quantifier::ZeroOrOne, pi + 1),
        '*' => (Quantifier::ZeroOrMore, pi + 1),
        '+' => (Quantifier::OneOrMore, pi + 1),
        '{' => {
            // Parse {n}, {n,}, {n,m}
            let mut i = pi + 1;
            let mut n_str = String::new();
            while i < pat.len() && pat[i].is_ascii_digit() {
                n_str.push(pat[i]);
                i += 1;
            }
            if n_str.is_empty() {
                return (Quantifier::One, pi);
            }
            let n: usize = n_str.parse().unwrap_or(0);
            if i < pat.len() && pat[i] == '}' {
                return (Quantifier::Exactly(n), i + 1);
            }
            if i < pat.len() && pat[i] == ',' {
                i += 1;
                let mut m_str = String::new();
                while i < pat.len() && pat[i].is_ascii_digit() {
                    m_str.push(pat[i]);
                    i += 1;
                }
                if i < pat.len() && pat[i] == '}' {
                    if m_str.is_empty() {
                        return (Quantifier::AtLeast(n), i + 1);
                    } else {
                        let m: usize = m_str.parse().unwrap_or(0);
                        return (Quantifier::Between(n, m), i + 1);
                    }
                }
            }
            (Quantifier::One, pi)
        }
        _ => (Quantifier::One, pi),
    }
}

fn find_group_end(pat: &[char], pi: usize) -> (usize, Vec<char>) {
    // pi points to '('
    let mut i = pi + 1;
    let mut depth = 1usize;
    let mut content = Vec::new();
    while i < pat.len() {
        match pat[i] {
            '(' => { depth += 1; content.push(pat[i]); }
            ')' => {
                depth -= 1;
                if depth == 0 {
                    return (i + 1, content);
                }
                content.push(pat[i]);
            }
            '\\' if i + 1 < pat.len() => {
                content.push(pat[i]);
                content.push(pat[i + 1]);
                i += 1;
            }
            c => content.push(c),
        }
        i += 1;
    }
    (i, content)
}

fn split_alt(content: &[char]) -> Vec<Vec<char>> {
    let mut alts: Vec<Vec<char>> = Vec::new();
    let mut current = Vec::new();
    let mut depth = 0usize;
    let mut i = 0;
    while i < content.len() {
        match content[i] {
            '(' => { depth += 1; current.push(content[i]); }
            ')' => { depth -= 1; current.push(content[i]); }
            '|' if depth == 0 => {
                alts.push(current.clone());
                current.clear();
            }
            '\\' if i + 1 < content.len() => {
                current.push(content[i]);
                current.push(content[i + 1]);
                i += 1;
            }
            c => current.push(c),
        }
        i += 1;
    }
    alts.push(current);
    alts
}
