use std::process;
use crate::csv_core::{CsvConfig, CsvReader, CsvWriter, open_input, open_output};
use crate::util::{Args, args_for_command};
use crate::select::Selection;

const USAGE: &str = "
Filters CSV data by whether the given regex matches a row.

The regex is applied to each field in each row, and if any field matches,
then the row is written to the output. The columns to search can be limited
with the '--select' flag (but the full row is still written to the output if
there is a match).

Usage:
    xsv search [options] <regex> [<input>]
    xsv search --help

search options:
    -i, --ignore-case      Case insensitive search. This is equivalent to
                           prefixing the regex with '(?i)'.
    -s, --select <arg>     Select the columns to search. See 'xsv select -h'
                           for the full syntax.
    -v, --invert-match     Select only rows that did not match

Common options:
    -h, --help             Display this message
    -o, --output <file>    Write output to <file> instead of stdout.
    -n, --no-headers       When set, the first row will not be interpreted
                           as headers. (i.e., They are not searched, analyzed,
                           sliced, etc.)
    -d, --delimiter <arg>  The field delimiter for reading CSV data.
                           Must be a single character. (default: ,)
";

pub fn run(args: &[String]) {
    let a = args_for_command(args, &["--select", "-s"]);
    if a.flag2("--help", "-h") {
        print!("{}", USAGE);
        return;
    }

    let ignore_case = a.flag2("--ignore-case", "-i");
    let invert = a.flag2("--invert-match", "-v");
    let select = a.opt2("--select", "-s");
    let no_headers = !a.has_headers();
    let delimiter = a.delimiter();
    let output_path = a.output_path();

    let pos = a.positional();

    if pos.is_empty() {
        eprintln!("Usage: xsv search [options] <regex> [<input>]");
        process::exit(1);
    }

    let regex_str = &pos[0];
    let input_path = pos.get(1).map(|s| s.as_str());

    // Build regex pattern
    let pattern = if ignore_case {
        format!("(?i){}", regex_str)
    } else {
        regex_str.clone()
    };

    let re = Regex::new(&pattern).unwrap_or_else(|e| {
        eprintln!("Invalid regex: {}", e);
        process::exit(1);
    });

    let config = CsvConfig {
        delimiter,
        quote: b'"',
        escape: None,
        no_quoting: false,
        has_headers: true,
    };

    let input = open_input(input_path).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let output = open_output(output_path.as_deref()).unwrap_or_else(|e| {
        eprintln!("{}", e);
        process::exit(1);
    });

    let mut reader = CsvReader::new(input, config);
    let mut writer = CsvWriter::new(output).with_delimiter(delimiter);
    let mut record = crate::csv_core::Record::new();

    let mut search_indices: Option<Vec<usize>> = None;

    if !no_headers {
        if !reader.read_record(&mut record).unwrap_or(false) {
            return;
        }
        let headers = record.fields.clone();

        if let Some(sel_str) = select {
            let sel = Selection::parse(sel_str).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            let indices = sel.indices(&headers).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                process::exit(1);
            });
            search_indices = Some(indices);
        }

        let header_refs: Vec<&[u8]> = headers.iter().map(|f| f.as_slice()).collect();
        writer.write_record(&header_refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    while reader.read_record(&mut record).unwrap_or(false) {
        let matched = if let Some(ref indices) = search_indices {
            indices.iter().any(|&i| {
                let field = record.get(i).unwrap_or(b"");
                let s = std::str::from_utf8(field).unwrap_or("");
                re.is_match(s)
            })
        } else {
            record.fields.iter().any(|f| {
                let s = std::str::from_utf8(f).unwrap_or("");
                re.is_match(s)
            })
        };

        let should_write = if invert { !matched } else { matched };

        if should_write {
            let refs: Vec<&[u8]> = record.fields.iter().map(|f| f.as_slice()).collect();
            writer.write_record(&refs).unwrap_or_else(|e| {
                eprintln!("{}", e);
                process::exit(1);
            });
        }
    }

    writer.flush().ok();
}

