impl Regex {
    pub fn new(pattern: &str, case_insensitive: bool) -> Result<Self, RegexError> {
        // Validate pattern
        let bytes = pattern.as_bytes();
        let mut i = 0;
        let mut depth = 0usize;
        while i < bytes.len() {
