            p.chars().collect::<Vec<_>>()
        } else {
            String::from_utf8_lossy(&self.pattern).chars().collect::<Vec<_>>()
        };

        let text_chars: Vec<char> = if self.case_insensitive {
            text.to_lowercase().chars().collect()
        } else {
            text.chars().collect()
        };

        regex_match(&pat, &text_chars)
    }
}

fn regex_match(pat: &[char], text: &[char]) -> bool {
    let (anchored_start, p) = if !pat.is_empty() && pat[0] == '^' {
        (true, &pat[1..])
    } else {
        (false, pat)
    };

    if anchored_start {
        match_pos(p, text, 0)
    } else {
        for i in 0..=text.len() {
            if match_pos(p, text, i) {
                return true;
            }
        }
        false
    }
}

fn match_pos(pat: &[char], text: &[char], start: usize) -> bool {
    match_at(pat, 0, text, start)
}

fn match_at(pat: &[char], pi: usize, text: &[char], ti: usize) -> bool {
    if pi >= pat.len() {
        return true;
    }

    // End anchor
    if pat[pi] == '$' && pi + 1 == pat.len() {
        return ti >= text.len();
    }

    // Group handling
    if pat[pi] == '(' {
        let (group_end, group_chars) = find_group(pat, pi);
        let (quant, next_pi) = parse_quantifier(pat, group_end);
        let alts = split_alternation(&group_chars);

        return match_group_with_quantifier(pat, &alts, quant, next_pi, text, ti);
    }

    // Regular atom
    let (atom_len, atom) = parse_atom(pat, pi);
    if atom_len == 0 {
        return match_at(pat, pi + 1, text, ti);
    }
    let (quant, next_pi) = parse_quantifier(pat, pi + atom_len);

    match quant {
        Quant::One => {
            if ti < text.len() && atom_match(&atom, text[ti]) {
                match_at(pat, next_pi, text, ti + 1)
            } else {
                false
            }
        }
        Quant::Question => {
            // Try zero first, then one
            if match_at(pat, next_pi, text, ti) { return true; }
            if ti < text.len() && atom_match(&atom, text[ti]) {
                match_at(pat, next_pi, text, ti + 1)
            } else {
                false
            }
        }
        Quant::Star => {
            // Try greedy, then back off
            let mut limit = ti;
            while limit < text.len() && atom_match(&atom, text[limit]) {
                limit += 1;
            }
            // Try from greedy to zero
            let mut cur = limit;
            loop {
                if match_at(pat, next_pi, text, cur) { return true; }
                if cur == ti { break; }
                cur -= 1;
            }
            false
        }
        Quant::Plus => {
            if ti >= text.len() || !atom_match(&atom, text[ti]) { return false; }
            let mut limit = ti + 1;
            while limit < text.len() && atom_match(&atom, text[limit]) {
                limit += 1;
            }
            let mut cur = limit;
            loop {
                if match_at(pat, next_pi, text, cur) { return true; }
                if cur == ti + 1 { break; }
                cur -= 1;
            }
            false
        }
        Quant::Exactly(n) => {
            let mut cur = ti;
            for _ in 0..n {
                if cur >= text.len() || !atom_match(&atom, text[cur]) { return false; }
                cur += 1;
            }
            match_at(pat, next_pi, text, cur)
        }
        Quant::AtLeast(n) => {
            let mut cur = ti;
            for _ in 0..n {
                if cur >= text.len() || !atom_match(&atom, text[cur]) { return false; }
                cur += 1;
            }
            // Then greedy
            let start = cur;
            while cur < text.len() && atom_match(&atom, text[cur]) {
                cur += 1;
            }
            let limit = cur;
            cur = limit;
            loop {
                if match_at(pat, next_pi, text, cur) { return true; }
                if cur == start { break; }
                cur -= 1;
            }
            false
        }
        Quant::Between(n, m) => {
            let mut cur = ti;
            for _ in 0..n {
                if cur >= text.len() || !atom_match(&atom, text[cur]) { return false; }
                cur += 1;
            }
            let start = cur;
            let mut count = n;
            // Greedy up to m
            while count < m && cur < text.len() && atom_match(&atom, text[cur]) {
                cur += 1;
                count += 1;
            }
            let limit = cur;
            cur = limit;
            loop {
                if match_at(pat, next_pi, text, cur) { return true; }
                if cur == start { break; }
                cur -= 1;
            }
            false
        }
    }
}

fn match_group_with_quantifier(pat: &[char], alts: &[Vec<char>], quant: Quant, next_pi: usize, text: &[char], ti: usize) -> bool {
    match quant {
        Quant::One => {
            for alt in alts {
                // Try to match alt starting at ti, consuming as many chars as possible
                for end in (ti..=text.len()).rev() {
                    if match_at(alt, 0, text, ti) && match_exact_group(alt, text, ti, end) {
                        if match_at(pat, next_pi, text, end) {
                            return true;
                        }
                    }
                }
            }
            false
        }
        Quant::Question => {
            if match_at(pat, next_pi, text, ti) { return true; }
            match_group_with_quantifier(pat, alts, Quant::One, next_pi, text, ti)
        }
        Quant::Star => {
            // Zero times
            if match_at(pat, next_pi, text, ti) { return true; }
            // One or more times: try greedy matching
            match_group_star(pat, alts, next_pi, text, ti)
        }
        Quant::Plus => {
            // One or more
            match_group_plus(pat, alts, next_pi, text, ti)
        }
        Quant::Exactly(n) => {
            match_group_repeat(pat, alts, n, next_pi, text, ti)
        }
        Quant::AtLeast(n) => {
            if !match_group_repeat_n(alts, n, text, ti) {
                return false;
            }
            // TODO: proper handling
            false
        }
        Quant::Between(n, _m) => {
            match_group_repeat(pat, alts, n, next_pi, text, ti)
        }
    }
}

fn match_group_star(pat: &[char], alts: &[Vec<char>], next_pi: usize, text: &[char], start: usize) -> bool {
    // Try matching group repeatedly, greedily
    let mut positions = vec![start];
    let mut cur = start;

    loop {
        let mut advanced = false;
        for alt in alts {
            for end in (cur + 1..=text.len()).rev() {
                if match_exact_group(alt, text, cur, end) {
                    positions.push(end);
                    cur = end;
                    advanced = true;
                    break;
                }
            }
            if advanced { break; }
        }
        if !advanced { break; }
    }

    for &pos in positions.iter().rev() {
        if match_at(pat, next_pi, text, pos) {
            return true;
        }
    }
    false
}

fn match_group_plus(pat: &[char], alts: &[Vec<char>], next_pi: usize, text: &[char], start: usize) -> bool {
    // Must match at least once
    for alt in alts {
        for first_end in (start + 1..=text.len()).rev() {
            if match_exact_group(alt, text, start, first_end) {
                // Now try star from first_end
                if match_at(pat, next_pi, text, first_end) { return true; }
                if match_group_star(pat, alts, next_pi, text, first_end) { return true; }
                break;
            }
        }
    }
    // Minimal match (1 char if possible)
    for alt in alts {
        for first_end in start + 1..=text.len() {
            if match_exact_group(alt, text, start, first_end) {
                if match_at(pat, next_pi, text, first_end) { return true; }
                if match_group_star(pat, alts, next_pi, text, first_end) { return true; }
                break;
            }
        }
    }
    false
}

fn match_group_repeat(pat: &[char], alts: &[Vec<char>], n: usize, next_pi: usize, text: &[char], start: usize) -> bool {
    if n == 0 {
        return match_at(pat, next_pi, text, start);
    }
    for alt in alts {
        for end in start + 1..=text.len() {
            if match_exact_group(alt, text, start, end) {
                if match_group_repeat(pat, alts, n - 1, next_pi, text, end) {
                    return true;
                }
            }
        }
    }
    false
}

fn match_group_repeat_n(alts: &[Vec<char>], n: usize, text: &[char], start: usize) -> bool {
    if n == 0 { return true; }
    for alt in alts {
        for end in start + 1..=text.len() {
            if match_exact_group(alt, text, start, end) {
                if match_group_repeat_n(alts, n - 1, text, end) {
                    return true;
                }
            }
        }
    }
    false
}

fn match_exact_group(pat: &[char], text: &[char], start: usize, end: usize) -> bool {
    // Match pat against text[start..end] exactly (consuming all chars)
    if start > end || end > text.len() { return false; }
    let slice = &text[start..end];
    match_exact(pat, 0, slice, 0)
}

fn match_exact(pat: &[char], pi: usize, text: &[char], ti: usize) -> bool {
    if pi >= pat.len() {
        return ti >= text.len();
    }
    if ti > text.len() { return false; }

