            match_group_with_quantifier(pat, alts, Quant::One, next_pi, text, ti)
        }
        Quant::Star => {
            // Zero times
            if match_at(pat, next_pi, text, ti) { return true; }
            // One or more times: try greedy matching
            match_group_star(pat, alts, next_pi, text, ti)
        }
        Quant::Plus => {
            // One or more
            match_group_plus(pat, alts, next_pi, text, ti)
        }
        Quant::Exactly(n) => {
            match_group_repeat(pat, alts, n, next_pi, text, ti)
        }
        Quant::AtLeast(n) => {
            if !match_group_repeat_n(alts, n, text, ti) {
                return false;
            }
            // TODO: proper handling
            false
        }
        Quant::Between(n, _m) => {
            match_group_repeat(pat, alts, n, next_pi, text, ti)
        }
    }
}

fn match_group_star(pat: &[char], alts: &[Vec<char>], next_pi: usize, text: &[char], start: usize) -> bool {
    // Try matching group repeatedly, greedily
    let mut positions = vec![start];
    let mut cur = start;

    loop {
        let mut advanced = false;
        for alt in alts {
            for end in (cur + 1..=text.len()).rev() {
                if match_exact_group(alt, text, cur, end) {
                    positions.push(end);
                    cur = end;
                    advanced = true;
                    break;
                }
            }
            if advanced { break; }
        }
        if !advanced { break; }
    }

    for &pos in positions.iter().rev() {
        if match_at(pat, next_pi, text, pos) {
            return true;
        }
    }
    false
}

fn match_group_plus(pat: &[char], alts: &[Vec<char>], next_pi: usize, text: &[char], start: usize) -> bool {
    // Must match at least once
    for alt in alts {
        for first_end in (start + 1..=text.len()).rev() {
            if match_exact_group(alt, text, start, first_end) {
                // Now try star from first_end
                if match_at(pat, next_pi, text, first_end) { return true; }
                if match_group_star(pat, alts, next_pi, text, first_end) { return true; }
                break;
            }
        }
    }
    // Minimal match (1 char if possible)
    for alt in alts {
        for first_end in start + 1..=text.len() {
            if match_exact_group(alt, text, start, first_end) {
                if match_at(pat, next_pi, text, first_end) { return true; }
                if match_group_star(pat, alts, next_pi, text, first_end) { return true; }
                break;
            }
        }
    }
    false
}

fn match_group_repeat(pat: &[char], alts: &[Vec<char>], n: usize, next_pi: usize, text: &[char], start: usize) -> bool {
    if n == 0 {
        return match_at(pat, next_pi, text, start);
    }
    for alt in alts {
        for end in start + 1..=text.len() {
            if match_exact_group(alt, text, start, end) {
                if match_group_repeat(pat, alts, n - 1, next_pi, text, end) {
                    return true;
                }
            }
        }
    }
    false
}

fn match_group_repeat_n(alts: &[Vec<char>], n: usize, text: &[char], start: usize) -> bool {
    if n == 0 { return true; }
    for alt in alts {
        for end in start + 1..=text.len() {
            if match_exact_group(alt, text, start, end) {
                if match_group_repeat_n(alts, n - 1, text, end) {
                    return true;
                }
            }
        }
    }
    false
}

fn match_exact_group(pat: &[char], text: &[char], start: usize, end: usize) -> bool {
    // Match pat against text[start..end] exactly (consuming all chars)
    if start > end || end > text.len() { return false; }
    let slice = &text[start..end];
    match_exact(pat, 0, slice, 0)
}

fn match_exact(pat: &[char], pi: usize, text: &[char], ti: usize) -> bool {
    if pi >= pat.len() {
        return ti >= text.len();
    }
    if ti > text.len() { return false; }

    if pat[pi] == '$' && pi + 1 == pat.len() {
        return ti >= text.len();
    }

    if pat[pi] == '(' {
        let (group_end, group_chars) = find_group(pat, pi);
        let (quant, next_pi) = parse_quantifier(pat, group_end);
        let alts = split_alternation(&group_chars);

        return match_group_exact(pat, &alts, quant, next_pi, text, ti);
    }

    let (atom_len, atom) = parse_atom(pat, pi);
    if atom_len == 0 { return match_exact(pat, pi + 1, text, ti); }
    let (quant, next_pi) = parse_quantifier(pat, pi + atom_len);

    match quant {
        Quant::One => {
            if ti < text.len() && atom_match(&atom, text[ti]) {
                match_exact(pat, next_pi, text, ti + 1)
            } else {
                false
            }
        }
        Quant::Question => {
            if match_exact(pat, next_pi, text, ti) { return true; }
            if ti < text.len() && atom_match(&atom, text[ti]) {
                match_exact(pat, next_pi, text, ti + 1)
            } else {
                false
            }
        }
        Quant::Star => {
            let mut limit = ti;
            while limit < text.len() && atom_match(&atom, text[limit]) { limit += 1; }
            let mut cur = limit;
            loop {
                if match_exact(pat, next_pi, text, cur) { return true; }
                if cur == ti { break; }
                cur -= 1;
            }
            false
        }
        Quant::Plus => {
            if ti >= text.len() || !atom_match(&atom, text[ti]) { return false; }
            let mut limit = ti + 1;
            while limit < text.len() && atom_match(&atom, text[limit]) { limit += 1; }
            let mut cur = limit;
            loop {
                if match_exact(pat, next_pi, text, cur) { return true; }
                if cur == ti + 1 { break; }
                cur -= 1;
            }
            false
        }
        Quant::Exactly(n) => {
            let mut cur = ti;
            for _ in 0..n {
                if cur >= text.len() || !atom_match(&atom, text[cur]) { return false; }
                cur += 1;
            }
            match_exact(pat, next_pi, text, cur)
        }
        _ => false,
    }
}

fn match_group_exact(pat: &[char], alts: &[Vec<char>], quant: Quant, next_pi: usize, text: &[char], ti: usize) -> bool {
    match quant {
        Quant::One => {
            for alt in alts {
                for end in ti..=text.len() {
                    if match_exact(alt, 0, &text[ti..], 0) && (end - ti) == 0 
                       || match_exact_at(alt, text, ti, end) {
                        if match_exact(pat, next_pi, text, end) {
                            return true;
                        }
                    }
                }
            }
            false
        }
        Quant::Question => {
            if match_exact(pat, next_pi, text, ti) { return true; }
            for alt in alts {
                for end in ti + 1..=text.len() {
                    if match_exact_at(alt, text, ti, end) {
                        if match_exact(pat, next_pi, text, end) {
                            return true;
                        }
                    }
                }
            }
            false
        }
        _ => false,
    }
}

fn match_exact_at(pat: &[char], text: &[char], start: usize, end: usize) -> bool {
    if start > end || end > text.len() { return false; }
    match_exact(pat, 0, &text[start..end], 0)
}

#[derive(Debug, Clone)]
enum Quant {
    One,
    Question,
    Star,
    Plus,
    Exactly(usize),
    AtLeast(usize),
    Between(usize, usize),
}

#[derive(Debug)]
enum AtomType {
    Literal(char),
    Dot,
    Class(Vec<(char, char)>, bool), // (from, to) ranges, negated
    Digit,
    NonDigit,
    Word,
    NonWord,
    Space,
    NonSpace,
}

fn atom_match(atom: &AtomType, c: char) -> bool {
    match atom {
        AtomType::Literal(ch) => c == *ch,
        AtomType::Dot => c != '\n',
        AtomType::Class(ranges, neg) => {
            let in_class = ranges.iter().any(|(lo, hi)| c >= *lo && c <= *hi);
            if *neg { !in_class } else { in_class }
        }
        AtomType::Digit => c.is_ascii_digit(),
        AtomType::NonDigit => !c.is_ascii_digit(),
        AtomType::Word => c.is_alphanumeric() || c == '_',
        AtomType::NonWord => !(c.is_alphanumeric() || c == '_'),
        AtomType::Space => c.is_ascii_whitespace(),
        AtomType::NonSpace => !c.is_ascii_whitespace(),
    }
}

fn parse_atom(pat: &[char], pi: usize) -> (usize, AtomType) {
    if pi >= pat.len() {
        return (0, AtomType::Literal(' '));
    }
    match pat[pi] {
        '.' => (1, AtomType::Dot),
        '\\' if pi + 1 < pat.len() => {
            let (len, atom) = match pat[pi + 1] {
                'd' => (2, AtomType::Digit),
                'D' => (2, AtomType::NonDigit),
                'w' => (2, AtomType::Word),
                'W' => (2, AtomType::NonWord),
                's' => (2, AtomType::Space),
                'S' => (2, AtomType::NonSpace),
                c => (2, AtomType::Literal(c)),
            };
            (len, atom)
        }
        '[' => {
            let (end, ranges, neg) = parse_class(pat, pi);
            (end - pi, AtomType::Class(ranges, neg))
        }
        '(' | ')' | '*' | '+' | '?' | '{' | '^' | '$' | '|' => {
            // These aren't literal atoms; return 0 to signal special handling
            // Actually for '$' and '|' they shouldn't appear here as atoms
            // For '(' and ')' they're handled above
            // For quantifiers, they're handled in the quantifier parser
            // Let's just handle them as literals for robustness
            (1, AtomType::Literal(pat[pi]))
        }
        c => (1, AtomType::Literal(c)),
    }
}

fn parse_class(pat: &[char], pi: usize) -> (usize, Vec<(char, char)>, bool) {
    let mut i = pi + 1;
    let neg = if i < pat.len() && pat[i] == '^' { i += 1; true } else { false };
    let mut ranges = Vec::new();

    // First char can be ] literally
    if i < pat.len() && pat[i] == ']' {
        ranges.push((']', ']'));
        i += 1;
    }

    while i < pat.len() && pat[i] != ']' {
        if i + 2 < pat.len() && pat[i + 1] == '-' && pat[i + 2] != ']' {
            ranges.push((pat[i], pat[i + 2]));
            i += 3;
        } else if pat[i] == '\\' && i + 1 < pat.len() {
            let c = match pat[i + 1] {
                'n' => '\n',
                't' => '\t',
                'r' => '\r',
                c => c,
            };
            ranges.push((c, c));
            i += 2;
        } else {
            ranges.push((pat[i], pat[i]));
            i += 1;
        }
    }

    (i + 1, ranges, neg)
}

fn parse_quantifier(pat: &[char], pi: usize) -> (Quant, usize) {
    if pi >= pat.len() { return (Quant::One, pi); }
    match pat[pi] {
        '?' => (Quant::Question, pi + 1),
        '*' => (Quant::Star, pi + 1),
        '+' => (Quant::Plus, pi + 1),
        '{' => {
            let mut i = pi + 1;
            let mut n_s = String::new();
            while i < pat.len() && pat[i].is_ascii_digit() { n_s.push(pat[i]); i += 1; }
            if n_s.is_empty() { return (Quant::One, pi); }
            let n = n_s.parse::<usize>().unwrap_or(1);
            if i < pat.len() && pat[i] == '}' { return (Quant::Exactly(n), i + 1); }
            if i < pat.len() && pat[i] == ',' {
                i += 1;
                let mut m_s = String::new();
                while i < pat.len() && pat[i].is_ascii_digit() { m_s.push(pat[i]); i += 1; }
                if i < pat.len() && pat[i] == '}' {
                    if m_s.is_empty() { return (Quant::AtLeast(n), i + 1); }
                    let m = m_s.parse::<usize>().unwrap_or(n);
                    return (Quant::Between(n, m), i + 1);
                }
            }
            (Quant::One, pi)
        }
        _ => (Quant::One, pi),
    }
}

fn find_group(pat: &[char], pi: usize) -> (usize, Vec<char>) {
    let mut i = pi + 1;
    let mut depth = 1;
    let mut content = Vec::new();
    while i < pat.len() {
        match pat[i] {
            '(' => { depth += 1; content.push(pat[i]); }
            ')' => {
                depth -= 1;
                if depth == 0 { return (i + 1, content); }
                content.push(pat[i]);
            }
            '\\' if i + 1 < pat.len() => {
                content.push(pat[i]);
                content.push(pat[i + 1]);
                i += 1;
            }
            c => content.push(c),
        }
        i += 1;
    }
    (i, content)
}

fn split_alternation(content: &[char]) -> Vec<Vec<char>> {
    let mut alts = Vec::new();
    let mut current = Vec::new();
    let mut depth = 0;
    let mut i = 0;
    while i < content.len() {
        match content[i] {
            '(' => { depth += 1; current.push(content[i]); }
            ')' => { depth -= 1; current.push(content[i]); }
            '|' if depth == 0 => {
                alts.push(std::mem::take(&mut current));
            }
            '\\' if i + 1 < content.len() => {
                current.push(content[i]);
                current.push(content[i + 1]);
                i += 1;
            }
            c => current.push(c),
        }
        i += 1;
    }
    alts.push(current);
    alts
}
