            } else {
                for _ in 0..header.len() {
                    combined_row.push(Vec::new());
                }
            }
        }
        let refs: Vec<&[u8]> = combined_row.iter().map(|f| f.as_slice()).collect();
        writer.write_record(&refs).unwrap_or_else(|e| {
            eprintln!("{}", e);
            process::exit(1);
        });
    }

    writer.flush().ok();
}
